# ---------- Component values ----------
@dataclass
class Comp:
    kind: str  # tok, func, block
    token: object = None
    children: list = field(default_factory=list)
    closed: bool = True

def build_components(toks, start=0, end=None, stop_types=None):
    if end is None: end=len(toks)
    comps=[]; i=start
    while i<end:
        t=toks[i]
        if stop_types and t.type in stop_types:
            break
        if t.type=='FUNCTION':
            depth=1; j=i+1
            while j<end and depth>0:
                if toks[j].type in ('FUNCTION','LPAREN'): depth+=1
                elif toks[j].type=='RPAREN': depth-=1
                j+=1
            inner_end=j-1 if depth==0 else j
            children,_=build_components(toks,i+1,inner_end)
            comps.append(Comp('func',t,children,depth==0)); i=j; continue
        if t.type in ('LPAREN','LBRACK','LBRACE'):
            close={'LPAREN':'RPAREN','LBRACK':'RBRACK','LBRACE':'RBRACE'}[t.type]
            # count nested of all brackets naively by matching type pairs with a stack
            stack=[t.type]; j=i+1
            while j<end and stack:
                tt=toks[j].type
                if tt in ('LPAREN','LBRACK','LBRACE','FUNCTION'):
                    stack.append('LPAREN' if tt=='FUNCTION' else tt)
                elif tt in ('RPAREN','RBRACK','RBRACE'):
                    # pop matching or any
                    if stack: stack.pop()
                j+=1
            inner_end=j-1 if not stack else j
            children,_=build_components(toks,i+1,inner_end)
            comps.append(Comp('block',t,children,not stack)); i=j; continue
        if t.type in ('RPAREN','RBRACK','RBRACE'):
            # unmatched close treat as token
            comps.append(Comp('tok',t)); i+=1; continue
        comps.append(Comp('tok',t)); i+=1
    return comps,i

def is_ws(c): return c.kind=='tok' and c.token.type=='WS'
def is_comment(c): return c.kind=='tok' and c.token.type=='COMMENT'
def meaningful(comps):
    return [c for c in comps if not (c.kind=='tok' and c.token.type in ('WS','COMMENT'))]
def tok_type(c):
    return c.token.type if c.kind=='tok' else None
def split_commas(comps):
    parts=[[]]
    for c in comps:
        if c.kind=='tok' and c.token.type=='COMMA': parts.append([])
        else: parts[-1].append(c)
    return parts
def split_top(comps, delim_value=None, token_type=None):
    parts=[[]]
    for c in comps:
        if c.kind=='tok' and ((token_type and c.token.type==token_type) or (delim_value and c.token.type=='DELIM' and c.token.value==delim_value)):
            parts.append([])
        else: parts[-1].append(c)
    return parts

