LENGTH_UNITS=set(ABSOLUTE_LENGTH)|{'em','rem','ex','cap','ch','ic','lh','rlh','vw','vh','vmin','vmax','vi','vb','svw','svh','svmin','svmax','svi','svb','lvw','lvh','lvmin','lvmax','lvi','lvb','dvw','dvh','dvmin','dvmax','dvi','dvb','cqw','cqh','cqmin','cqmax','cqi','cqb'}
ANGLE_UNITS={'deg','grad','rad','turn'}
TIME_UNITS={'s','ms'}
FREQ_UNITS={'hz','khz'}
RES_UNITS={'dpi','dpcm','dppx','x'}

def angle_to_deg(v,u):
    if u=='deg': return v
    if u=='rad': return v*180.0/math.pi
    if u=='grad': return v*0.9
    if u=='turn': return v*360.0
    return v
def time_to_s(v,u):
    return v/1000.0 if u=='ms' else v

def format_time(v_s):
    v=f32(v_s)
    if v==0: return "0s"
    cand_s=fmt_num(v)+"s"; cand_ms=fmt_num(f32(v*1000))+"ms"
    return cand_s if len(cand_s)<=len(cand_ms) else cand_ms

@dataclass
class Leaf:
    kind: str # number percent dim raw
    value: float=0.0
    unit: str=""
    text: str=""
    def copy(self): return Leaf(self.kind,self.value,self.unit,self.text)
    def to_text(self, ox):
        if self.kind=='raw': return self.text
        if self.kind=='number': return fmt_num(self.value)
        if self.kind=='percent': return fmt_num(self.value)+'%'
        if self.kind=='dim':
            if self.unit in TIME_UNITS:
                # value stored in original unit, canonical format
                return format_time(time_to_s(self.value,self.unit))
            return fmt_num(self.value)+self.unit
        return self.text

# calc AST: tuples ('leaf', Leaf) ('sum',[terms]) ('mul',a,b) ('div',a,b) ('func',name,[args]) ('neg',a) ('raw',text)
def leaf_from_comp(c, ox):
    if c.kind=='tok':
        t=c.token
        if t.type=='NUMBER': return Leaf('number',f32(t.value))
        if t.type=='PERCENT': return Leaf('percent',f32(t.value))
        if t.type=='DIM':
            v,u=t.value; u=u.lower()
            if u=='rad': return Leaf('dim',f32(angle_to_deg(v,u)),'deg')
            if u=='dppx': u='x'
            return Leaf('dim',f32(v),u)
        if t.type=='IDENT':
            lv=t.value.lower()
            if lv=='pi': return Leaf('number',f32(math.pi))
            if lv=='e': return Leaf('number',f32(math.e))
            if lv=='infinity': return Leaf('raw',text='infinity')
            if lv=='-infinity': return Leaf('raw',text='-infinity')
            if lv=='nan': return Leaf('raw',text='NaN')
            return Leaf('raw',text=t.value)
    return None

def convert_leaf_pair(a,b):
    # returns (av,bv, kind, unit) if comparable combinable
    if a.kind=='raw' or b.kind=='raw': return None
    if a.kind==b.kind and a.kind in ('number','percent'):
        return (a.value,b.value,a.kind,'')
    if a.kind=='dim' and b.kind=='dim':
        ua,ub=a.unit,b.unit
        if ua==ub: return (a.value,b.value,'dim',ua)
        if ua in ABSOLUTE_LENGTH and ub in ABSOLUTE_LENGTH:
            return (a.value*ABSOLUTE_LENGTH[ua], b.value*ABSOLUTE_LENGTH[ub], 'dim','px')
        if ua in ANGLE_UNITS and ub in ANGLE_UNITS:
            return (angle_to_deg(a.value,ua), angle_to_deg(b.value,ub), 'dim','deg')
        if ua in TIME_UNITS and ub in TIME_UNITS:
            return (time_to_s(a.value,ua), time_to_s(b.value,ub), 'dim','s')
        if ua in FREQ_UNITS and ub in FREQ_UNITS:
            va=a.value*(1000 if ua=='khz' else 1); vb=b.value*(1000 if ub=='khz' else 1)
            return (va,vb,'dim','hz')
        if ua in RES_UNITS and ub in RES_UNITS:
            def tox(v,u): return v/96.0 if u=='dpi' else v/37.7952755906 if u=='dpcm' else v
            return (tox(a.value,ua),tox(b.value,ub),'dim','x')
    return None

def negate_ast(a):
    if a[0]=='leaf' and a[1].kind!='raw':
        l=a[1].copy(); l.value=f32(-l.value); return ('leaf',l)
    if a[0]=='neg': return a[1]
    if a[0]=='sum': return ('sum',[negate_ast(x) for x in a[1]])
    return ('neg',a)

def add_ast(a,b,sub=False):
    if sub: b=negate_ast(b)
    terms=[]
    for t in (a[1] if a[0]=='sum' else [a]) + (b[1] if b[0]=='sum' else [b]):
        terms.append(t)
    # combine leaf terms by unit/category in first appearance order
    out=[]
    for t in terms:
        if t[0]=='leaf' and t[1].kind!='raw':
            combined=False
            for idx,o in enumerate(out):
                if o[0]=='leaf' and o[1].kind!='raw':
                    cv=convert_leaf_pair(o[1],t[1])
                    if cv:
                        va,vb,kind,unit=cv
                        nv=f32(va+vb)
                        out[idx]=('leaf',Leaf(kind,nv,unit)); combined=True; break
            if combined: continue
            # zero leaves: keep only if sole eventually
            out.append(t)
        else:
            out.append(t)
    # remove zero leaf terms if more than one term
    if len(out)>1:
        out=[t for t in out if not (t[0]=='leaf' and t[1].kind!='raw' and t[1].value==0)]
        if not out: out=[('leaf',Leaf('number',0.0))]
    if len(out)==1: return out[0]
    return ('sum',out)

def mul_ast(a,b):
    if a[0]=='leaf' and b[0]=='leaf' and a[1].kind!='raw' and b[1].kind!='raw':
        la,lb=a[1],b[1]
        if la.kind=='number' and lb.kind=='number': return ('leaf',Leaf('number',f32(la.value*lb.value)))
        if la.kind=='number': l=lb.copy(); l.value=f32(l.value*la.value); return ('leaf',l)
        if lb.kind=='number': l=la.copy(); l.value=f32(l.value*lb.value); return ('leaf',l)
        return ('mul',a,b)
    # scalar * sum distribute when scalar leaf number
    for x,y in ((a,b),(b,a)):
        if x[0]=='leaf' and x[1].kind=='number' and y[0]=='sum':
            return ('sum',[mul_ast(x,t) for t in y[1]]) if all(mul_ast(x,t)[0]!='mul' for t in y[1]) else ('mul',a,b)
        if x[0]=='leaf' and x[1].kind=='number' and x[1].value==1:
            return y
    return ('mul',a,b)

def div_ast(a,b):
    if a[0]=='leaf' and b[0]=='leaf' and a[1].kind!='raw' and b[1].kind!='raw':
        la,lb=a[1],b[1]
        if lb.kind=='number' and lb.value!=0:
            l=la.copy(); l.value=f32(la.value/lb.value); return ('leaf',l)
        cv=convert_leaf_pair(la,lb)
        if cv and lb.value!=0:
            return ('leaf',Leaf('number',f32(cv[0]/cv[1])))
        return ('div',a,b)
    if b[0]=='leaf' and b[1].kind=='number' and a[0]=='sum' and b[1].value!=0:
        parts=[div_ast(t,b) for t in a[1]]
        if all(p[0]=='leaf' for p in parts): return ('sum',parts) if len(parts)>1 else parts[0]
    return ('div',a,b)

class CalcParser:
    def __init__(self, comps, ox):
        self.comps=meaningful(comps); self.i=0; self.ox=ox
    def peek(self): return self.comps[self.i] if self.i<len(self.comps) else None
    def next(self): c=self.peek(); self.i+=1; return c
    def parse(self):
        if not self.comps: raise ValueError('empty')
        a=self.parse_sum()
        if self.i!=len(self.comps): raise ValueError('trailing')
        return a
    def parse_sum(self):
        a=self.parse_product()
        while True:
            c=self.peek()
            if c and c.kind=='tok' and c.token.type=='DELIM' and c.token.value in '+-':
                self.next(); b=self.parse_product(); a=add_ast(a,b,sub=(c.token.value=='-'))
            else: return a
    def parse_product(self):
        a=self.parse_unary()
        while True:
            c=self.peek()
            if c and c.kind=='tok' and c.token.type=='DELIM' and c.token.value=='*':
                self.next(); a=mul_ast(a,self.parse_unary())
            elif c and c.kind=='tok' and c.token.type=='DELIM' and c.token.value=='/':
                self.next(); a=div_ast(a,self.parse_unary())
            else: return a
    def parse_unary(self):
        c=self.peek()
        if c and c.kind=='tok' and c.token.type=='DELIM' and c.token.value=='-':
            self.next(); return negate_ast(self.parse_unary())
        if c and c.kind=='tok' and c.token.type=='DELIM' and c.token.value=='+':
            self.next(); return self.parse_unary()
        return self.parse_atom()
    def parse_atom(self):
        c=self.next()
        if c is None: raise ValueError('eof')
        if c.kind=='block' and c.token.type=='LPAREN':
            return CalcParser(c.children,self.ox).parse()
        if c.kind=='func':
            return eval_math_function(c,self.ox, in_calc=True)
        lf=leaf_from_comp(c,self.ox)
        if lf is not None: return ('leaf',lf)
        raise ValueError('bad atom')

def calc_ast_to_text(a, ox, prec=0):
    if a[0]=='leaf': return a[1].to_text(ox)
    if a[0]=='raw': return a[1]
    if a[0]=='neg':
        inner=calc_ast_to_text(a[1],ox,3)
        return f"-{inner}"
    if a[0]=='sum':
        parts=[]
        for idx,t in enumerate(a[1]):
            if idx==0: parts.append(calc_ast_to_text(t,ox,1))
            else:
                if t[0]=='leaf' and t[1].kind!='raw' and t[1].value<0:
                    l=t[1].copy(); l.value=abs(l.value); parts.append(" - "+l.to_text(ox))
                elif t[0]=='neg': parts.append(" - "+calc_ast_to_text(t[1],ox,1))
                else: parts.append(" + "+calc_ast_to_text(t,ox,1))
        s=''.join(parts)
        return f"({s})" if prec>1 else s
    if a[0]=='mul':
        s=calc_ast_to_text(a[1],ox,2)+"*"+calc_ast_to_text(a[2],ox,3)
        return f"({s})" if prec>2 else s
    if a[0]=='div':
        s=calc_ast_to_text(a[1],ox,2)+" / "+calc_ast_to_text(a[2],ox,3)
        return f"({s})" if prec>2 else s
    if a[0]=='func':
        comma=', ' if not ox.minify else ','
        return f"{a[1]}({comma.join(calc_ast_to_text(x,ox) for x in a[2])})"
    return ""

def eval_math_function(c, ox, in_calc=False):
    name=c.token.value  # case sensitive for var
    lname=name.lower()
    if lname=='calc' and name.lower()==name or lname=='calc':
        # CSS math function names are case-insensitive except var/env distinction handled below
        pass
    if name=='var' or name=='env':
        return ('raw', comp_to_text_typed(c, ox))
    if lname in ('calc',):
        return CalcParser(c.children, ox).parse()
    if lname in ('min','max','clamp','round','mod','rem','sin','cos','tan','asin','acos','atan','atan2','pow','sqrt','hypot','log','exp','abs','sign'):
        argcomps=split_commas(c.children)
        args=[]; raw_args=[]
        ok=True
        for ac in argcomps:
            # round strategy idents are not expressions directly; CalcParser will make raw leaf
            try: args.append(CalcParser(ac,ox).parse())
            except Exception: ok=False; break
        if not ok:
            return ('raw', comp_to_text_typed(c,ox))
        # constant fold if all leaves
        folded=try_fold_math(lname,args,ox)
        if folded is not None: return folded
        # clamp lowering happens at target level later - keep func
        return ('func',lname,args)
    return ('raw', comp_to_text_typed(c,ox))

def try_fold_math(name,args,ox):
    # only if all leaf non-raw (except round strategy raw ident)
    if name=='round':
        # args: [value, step] or [strategy(raw), value, step]
        strat='nearest'; vals=args
        if args and args[0][0]=='leaf' and args[0][1].kind=='raw':
            strat=args[0][1].text.lower(); vals=args[1:]
        if len(vals)==2 and all(a[0]=='leaf' and a[1].kind!='raw' for a in vals):
            cv=convert_leaf_pair(vals[0][1],vals[1][1])
            if cv:
                va,vb,kind,unit=cv
                if vb==0: return None
                q=va/vb
                if strat=='up': n=math.ceil(q)
                elif strat=='down': n=math.floor(q)
                elif strat=='to-zero': n=math.trunc(q)
                else: n=math.floor(q+0.5) if q>=0 else math.ceil(q-0.5)
                return ('leaf',Leaf(kind,f32(n*vb),unit))
        return None
    if not all(a[0]=='leaf' and a[1].kind!='raw' for a in args): return None
    leaves=[a[1] for a in args]
    if name in ('min','max') and leaves:
        # compare after conversion to first
        convs=[]
        for l in leaves:
            cv=convert_leaf_pair(leaves[0],l)
            if not cv: return None
            convs.append(cv[1])
        idx=(min if name=='min' else max)(range(len(leaves)), key=lambda i: convs[i])
        return ('leaf',leaves[idx].copy())
    if name=='clamp' and len(leaves)==3:
        convs=[]
        for l in leaves:
            cv=convert_leaf_pair(leaves[0],l)
            if not cv: return None
            convs.append(cv[1])
        val=max(convs[0], min(convs[1],convs[2]))
        idx=convs.index(val) if val in convs else 1
        return ('leaf',leaves[idx].copy())
    if name in ('mod','rem') and len(leaves)==2:
        cv=convert_leaf_pair(leaves[0],leaves[1])
        if cv and cv[1]!=0:
            r=cv[0]%cv[1] if name=='mod' else math.fmod(cv[0],cv[1])
            return ('leaf',Leaf(cv[2],f32(r),cv[3]))
        return None
    if name in ('sin','cos','tan') and len(leaves)==1:
        l=leaves[0]
        if l.kind=='dim' and l.unit in ANGLE_UNITS:
            rad=math.radians(angle_to_deg(l.value,l.unit)); fn={'sin':math.sin,'cos':math.cos,'tan':math.tan}[name]
            return ('leaf',Leaf('number',f32(fn(rad))))
        if l.kind=='number':
            fn={'sin':math.sin,'cos':math.cos,'tan':math.tan}[name]
            return ('leaf',Leaf('number',f32(fn(l.value))))
    if name in ('asin','acos','atan') and len(leaves)==1 and leaves[0].kind=='number':
        try:
            fn={'asin':math.asin,'acos':math.acos,'atan':math.atan}[name]
            return ('leaf',Leaf('dim',f32(math.degrees(fn(leaves[0].value))),'deg'))
        except Exception: return None
    if name=='atan2' and len(leaves)==2:
        cv=convert_leaf_pair(leaves[0],leaves[1])
        if cv: return ('leaf',Leaf('dim',f32(math.degrees(math.atan2(cv[0],cv[1]))),'deg'))
    if name=='sqrt' and len(leaves)==1 and leaves[0].kind=='number':
        return ('leaf',Leaf('number',f32(math.sqrt(leaves[0].value)))) if leaves[0].value>=0 else None
    if name=='pow' and len(leaves)==2 and all(l.kind=='number' for l in leaves):
        return ('leaf',Leaf('number',f32(math.pow(leaves[0].value,leaves[1].value))))
    if name=='exp' and len(leaves)==1 and leaves[0].kind=='number':
        return ('leaf',Leaf('number',f32(math.exp(leaves[0].value))))
    if name=='log' and leaves and all(l.kind=='number' for l in leaves):
        if len(leaves)==1: return ('leaf',Leaf('number',f32(math.log(leaves[0].value))))
        if len(leaves)==2: return ('leaf',Leaf('number',f32(math.log(leaves[0].value,leaves[1].value))))
    if name=='hypot' and leaves:
        convs=[]
        for l in leaves:
            cv=convert_leaf_pair(leaves[0],l)
            if not cv: return None
            convs.append(cv[1])
        kind=convert_leaf_pair(leaves[0],leaves[0])
        return ('leaf',Leaf(kind[2],f32(math.hypot(*convs)),kind[3]))
    if name=='abs' and len(leaves)==1:
        l=leaves[0].copy(); l.value=abs(l.value); return ('leaf',l)
    if name=='sign' and len(leaves)==1:
        l=leaves[0]; v=0 if l.value==0 else (1 if l.value>0 else -1)
        if l.kind=='number': return ('leaf',Leaf('number',float(v)))
        l2=l.copy(); l2.value=float(v)*(1 if l.kind!='dim' else 1); 
        # sign of dimension returns same type with 1 unit in CSS? Actually sign(length) returns number? keep leaf unit value v
        return ('leaf',l2)
    return None

