    for t in (a[1] if a[0]=='sum' else [a]) + (b[1] if b[0]=='sum' else [b]):
        terms.append(t)
    # combine leaf terms by unit/category in first appearance order
    out=[]
    for t in terms:
        if t[0]=='leaf' and t[1].kind!='raw':
            combined=False
            for idx,o in enumerate(out):
