# ---------- Color parsing ----------
def comp_leaf(c, ox):
    # return Leaf if numeric or calc folded
    if c is None: return None
    if c.kind=='func' and c.token.value.lower() in ('calc','min','max','clamp','round','mod','rem'):
        try:
            ast=eval_math_function(c,ox)
            if ast[0]=='leaf': return ast[1]
        except Exception: return None
        return None
    return leaf_from_comp(c,ox)

def channel_value(leaf):
    if leaf is None: return None
    if leaf.kind=='number': return clamp255(leaf.value)
    if leaf.kind=='percent': return clamp255(leaf.value*2.55)
    if leaf.kind=='raw' and leaf.text.lower()=='none': return 0
    return None

def alpha_byte(leaf):
    if leaf is None: return 255
    if leaf.kind=='number': return clamp255(max(0,min(1,leaf.value))*255)
    if leaf.kind=='percent': return clamp255(max(0,min(100,leaf.value))/100*255)
    if leaf.kind=='raw' and leaf.text.lower()=='none': return 0
    return None

def alpha_float(leaf):
    if leaf is None: return 1.0
    if leaf.kind=='number': return max(0,min(1,leaf.value))
    if leaf.kind=='percent': return max(0,min(100,leaf.value))/100
    return None

def hue_value(leaf):
    if leaf is None: return None
    if leaf.kind=='number': return leaf.value
    if leaf.kind=='dim' and leaf.unit in ANGLE_UNITS: return angle_to_deg(leaf.value,leaf.unit)
    if leaf.kind=='raw' and leaf.text.lower()=='none': return 0.0
    return None

def pct_value(leaf):
    if leaf is None: return None
    if leaf.kind=='percent': return max(0,min(100,leaf.value))/100
    if leaf.kind=='number': return leaf.value  # for hsl second arg may be calc result - treat? no
    if leaf.kind=='raw' and leaf.text.lower()=='none': return 0.0
    return None

def split_slash(comps):
    mu=meaningful(comps); groups=[[]]
    for c in mu:
        if _is_delim(c,'/'): groups.append([])
        else: groups[-1].append(c)
    return groups

def parse_color_function(c, ox):
    if c.kind!='func': return None
    name=c.token.value.lower()
    if name not in ('rgb','rgba','hsl','hsla','hwb','lab','lch','oklab','oklch','color','color-mix'):
        return None
    # relative color: starts with 'from'
    mu=meaningful(c.children)
    if mu and mu[0].kind=='tok' and mu[0].token.type=='IDENT' and mu[0].token.value.lower()=='from':
        return None
    try:
        if name in ('rgb','rgba'):
            return _parse_rgb(c,ox)
        if name in ('hsl','hsla'):
            return _parse_hsl(c,ox)
        if name=='hwb':
            return _parse_hwb(c,ox)
        if name in ('lab','lch','oklab','oklch','color'):
            return _parse_modern_color(name,c,ox)
        if name=='color-mix':
            return _parse_color_mix(c,ox)
    except Exception:
        return None
    return None

def _parse_rgb(c,ox):
    if any(x.kind=='tok' and x.token.type=='COMMA' for x in meaningful(c.children)):
        parts=split_commas(c.children)
        if len(parts) not in (3,4): return None
        vals=[]
        for p in parts:
            m=meaningful(p)
            if len(m)!=1: return None
            vals.append(comp_leaf(m[0],ox))
        r,g,b=(channel_value(vals[0]),channel_value(vals[1]),channel_value(vals[2]))
        a=alpha_byte(vals[3]) if len(vals)==4 else 255
        if None in (r,g,b,a): return None
        return Color('rgba',r,g,b,a)
    else:
        groups=split_slash(c.children)
        if len(groups[0])!=3: return None
        vals=[comp_leaf(x,ox) for x in groups[0]]
        r,g,b=(channel_value(vals[0]),channel_value(vals[1]),channel_value(vals[2]))
