    x=lr*0.4123907993+lg*0.3575843395+lb*0.1804807884
    y=lr*0.2126390059+lg*0.7151686788+lb*0.0721923152
    z=lr*0.0193308187+lg*0.1191947798+lb*0.9505321522
    # D65 -> D50 Bradford
    x2=x*1.0479298208405488+y*0.022946793341019088+z*(-0.05019222854313557)
    y2=x*0.029627815688159344+y*0.990434484573249+z*(-0.01707382502938514)
    z2=x*(-0.009243058152591178)+y*0.015055191490298152+z*0.7518742814281371
    xn,yn,zn=0.96422,1.0,0.82521
    def f(t): return t**(1/3) if t>0.008856 else 7.787*t+16/116
    fx,fy,fz=f(x2/xn),f(y2/yn),f(z2/zn)
    return (116*fy-16,500*(fx-fy),200*(fy-fz))

