        if len(m)>=2:
            lf=comp_leaf(m[-1],ox)
            if lf and lf.kind=='percent': pct=lf.value; m=m[:-1]
        else:
            lf=comp_leaf(m[-1],ox)
            if lf and lf.kind=='percent': return None
        if len(m)!=1: return None
        col=parse_color_from_comps(m,ox)
        return (col,pct)
