            if space=='oklab': return rgb_to_oklab(v[0],v[1],v[2])
            if space=='oklch':
                L,a,b=rgb_to_oklab(v[0],v[1],v[2]); return (L,math.hypot(a,b),math.degrees(math.atan2(b,a))%360)
