                import colorsys
                h,l,s=colorsys.rgb_to_hls(v[0]/255,v[1]/255,v[2]/255)
                if space=='hsl': return (h*360,s*100,l*100)
                # hwb approx
                w=min(v)/255 if False else min(v[0],v[1],v[2])/255; bl=1-max(v[0],v[1],v[2])/255
