                out.append(A[i]*w1+B[i]*w2)
        aout=(v1[3]*w1+v2[3]*w2)*alpha_mult
        alpha=None if aout>=0.999999 else f32(aout)
        if space=='lab': comps=[fmt_num(f32(out[0]))+'%',fmt_num(f32(out[1])),fmt_num(f32(out[2]))]
        elif space=='lch': comps=[fmt_num(f32(out[0]))+'%',fmt_num(f32(out[1])),fmt_num(f32(out[2]))]
        elif space=='oklab': comps=[fmt_num(f32(out[0]*100))+'%',fmt_num(f32(out[1])),fmt_num(f32(out[2]))]
        elif space=='oklch': comps=[fmt_num(f32(out[0]*100))+'%',fmt_num(f32(out[1])),fmt_num(f32(out[2]))]
        elif space=='hsl': comps=[fmt_num(f32(out[0])),fmt_num(f32(out[1]))+'%',fmt_num(f32(out[2]))+'%']
        else: comps=[fmt_num(f32(out[0])),fmt_num(f32(out[1]))+'%',fmt_num(f32(out[2]))+'%']
        return Color(space,comps=comps,alpha=alpha)
    return None

def parse_color_from_comps(comps,ox,allow_named=True):
    mu=meaningful(comps)
