KNOWN_PSEUDO_ELEMENTS=set('''after backdrop before cue cue-region first-letter first-line file-selector-button grammar-error highlight marker part placeholder selection slotted spelling-error target-text view-transition view-transition-group view-transition-image-pair view-transition-old view-transition-new -webkit-scrollbar -webkit-scrollbar-button -webkit-scrollbar-thumb -webkit-scrollbar-track -webkit-scrollbar-track-piece -webkit-scrollbar-corner -webkit-resizer -webkit-input-placeholder -webkit-search-decoration -webkit-search-cancel-button -webkit-search-results-button -webkit-search-results-decoration -webkit-slider-thumb -webkit-slider-runnable-track -webkit-progress-bar -webkit-progress-value -webkit-progress-inner-element -moz-range-thumb -moz-range-track -moz-range-progress -moz-placeholder -moz-selection -moz-focus-inner -ms-backdrop'''.split())

class SelectorParser:
    def __init__(self, toks, source, ox, nested=False, allow_relative=False, parent_parser=None):
        self.toks=[t for t in toks if t.type not in ('WS','COMMENT')]
        self.all_toks=toks
        self.i=0; self.source=source; self.ox=ox; self.nested=nested; self.allow_relative=allow_relative
        self.parent=parent_parser
    def peek(self,off=0):
        j=self.i+off
        return self.toks[j] if j<len(self.toks) else None
    def next(self):
        t=self.peek(); self.i+=1; return t
    def err(self, kind, friendly, token=None, col=None, line=None):
        if token is not None:
            raise ParseError(kind,friendly,self.source, token.line, token.end_col if col is None else col)
        # EOF
        ln,cl=self.source.eof_loc() if self.source else (0,1)
        raise ParseError(kind,friendly,self.source, ln, cl)
    def warn_pseudo(self, name, is_element, token, col):
        if not self.ox.error_recovery: return
        lname=name.lower()
        if lname.startswith('-'): return
        if is_element:
            if lname in KNOWN_PSEUDO_ELEMENTS: return
            msg=f"'{name}' is not recognized as a valid pseudo-element. Did you mean ':{name}' (pseudo-class) or is this a typo?"
        else:
            if lname in KNOWN_PSEUDO_CLASSES: return
            if lname in ('before','after','first-line','first-letter','selection','placeholder','marker','backdrop'): return
            msg=f"'{name}' is not recognized as a valid pseudo-class. Did you mean '::{name}' (pseudo-element) or is this a typo?"
        e=ParseError('','',self.source,token.line,col)
        sys.stderr.write(f"{msg} at {self.source.filename}:{token.line}:{col}\n")
    def parse_list(self):
        sels=[]
        while True:
            sel=self.parse_complex()
            sels.append(sel)
            t=self.peek()
            if t and t.type=='COMMA':
                self.next(); continue
            break
        if self.i < len(self.toks):
            t=self.peek()
            # unexpected following token
            raise ParseError(f"UnexpectedToken({token_debug(t)})", f"Unexpected token {token_debug(t)}", self.source, t.line, t.col)
        return sels
    def parse_complex(self):
        parts=[]  # list of (combinator_or_None, compound list)
        combinator=None
        leading=False
        # relative leading combinator
        t=self.peek()
        if t and t.type=='DELIM' and t.value in '>+~':
            if not (self.allow_relative or self.nested):
                self.err("SelectorError(EmptySelector)","Invalid empty selector",t, col=t.end_col)
            combinator=t.value; self.next(); leading=True
        elif t and t.type=='DELIM' and t.value=='|' and self.peek(1) and self.peek(1).type=='DELIM' and self.peek(1).value=='|':
            if not (self.allow_relative or self.nested): self.err("SelectorError(EmptySelector)","Invalid empty selector",t,col=t.end_col)
            combinator='||'; self.next(); self.next(); leading=True
        while True:
            compound=self.parse_compound()
            if not compound:
                t=self.peek()
                if leading or parts and combinator:
                    # dangling
                    if t: self.err("SelectorError(DanglingCombinator)","Invalid dangling combinator in selector",t,col=t.end_col)
                    else:
                        prev=self.toks[-1] if self.toks else None
                        if prev: self.err("SelectorError(DanglingCombinator)","Invalid dangling combinator in selector",prev,col=prev.end_col+ (2 if prev.space_before else 0))
                    return parts
                if t is None:
                    # empty item: location based on following/preceding comma or first token
                    if self.toks:
                        tt=self.toks[min(self.i,len(self.toks)-1)]
                        self.err("SelectorError(EmptySelector)","Invalid empty selector",tt,col=tt.end_col)
                    else: self.err("SelectorError(EmptySelector)","Invalid empty selector")
                else:
                    self.err("SelectorError(EmptySelector)","Invalid empty selector",t,col=t.end_col)
            parts.append((combinator,compound))
            combinator=None; leading=False
            t=self.peek()
            if t is None or t.type=='COMMA': break
            if t.type=='DELIM' and t.value in '>+~':
                combinator=t.value; self.next();
                nt=self.peek()
                if nt is None or nt.type=='COMMA':
                    # dangling: location at end (brace in original: use pseudo token from all toks? approximate with comb token +?)
                    # loc col set to end of selector prelude +1: use source token after ? We use comb token line and comb end+2 if spaces in raw not known
                    # Find in all_toks after this token: the '{' token is not included; use last token end + (1+space)
                    # best: parser will replace? use comb token
                    raise ParseError("SelectorError(DanglingCombinator)","Invalid dangling combinator in selector",self.source,t.line, t.end_col+2 if t.space_before else t.end_col+1)
                continue
            if t.type=='DELIM' and t.value=='|' and self.peek(1) and self.peek(1).type=='DELIM' and self.peek(1).value=='|':
                combinator='||'; self.next(); self.next(); continue
            if t.space_before:
                combinator=' '; continue
            # token starts a compound without combinator? parse_compound should have consumed; treat as descendant if space was on block etc.
            break
        return parts
    def namespace_prefix(self):
        # returns (prefix string or None marker) if a ns pattern consumed, else False sentinel
        t=self.peek(); t2=self.peek(1)
        if t and t2 and t2.type=='DELIM' and t2.value=='|' and not (self.peek(2) and self.peek(2).type=='DELIM' and self.peek(2).value=='='):
            # check third isn't another | (column combinator is between compounds, handled earlier)
            if self.peek(2) and self.peek(2).type=='DELIM' and self.peek(2).value=='|': return False
            if t.type=='IDENT' or (t.type=='DELIM' and t.value=='*'):
                ns=t.value; self.next(); self.next(); return ns
        if t and t.type=='DELIM' and t.value=='|' and not (t2 and ((t2.type=='DELIM' and t2.value=='|') or (t2.type=='DELIM' and t2.value=='='))):
            # empty prefix |name - only if next ident/star
            if t2 and (t2.type=='IDENT' or (t2.type=='DELIM' and t2.value=='*')):
                self.next(); return ''
        return False
    def parse_compound(self):
        comps=[]
        first=True
        pseudo_element_seen=False
        while True:
            t=self.peek()
            if t is None or t.type=='COMMA': break
            if not first and t.space_before: break
            if t.type=='DELIM' and t.value in '>+~': break
            if t.type=='DELIM' and t.value=='|' and self.peek(1) and self.peek(1).type=='DELIM' and self.peek(1).value=='|':
                if not first: break
            # post pseudo-element restriction: only pseudo classes allowed
            if pseudo_element_seen and not (t.type=='COLON' and not (self.peek(1) and self.peek(1).type=='COLON')):
                raise ParseError(f"SelectorError(UnexpectedSelectorAfterPseudoElement({token_debug(t)}))", f"Unexpected selector after pseudo element: {token_debug(t)}", self.source, t.line, t.end_col)
            # namespace/type at start
            if first:
                ns=self.namespace_prefix()
                if ns is not False:
                    t=self.peek()
                    if t and t.type=='IDENT':
                        comps.append(('type',ns,t.value)); self.next(); first=False; continue
                    if t and t.type=='DELIM' and t.value=='*':
                        comps.append(('type',ns,'*')); self.next(); first=False; continue
                    # ns alone invalid
                    comps.append(('type',ns,'')); first=False; continue
                t=self.peek()
                if t and t.type=='IDENT':
                    comps.append(('type',None,t.value)); self.next(); first=False; continue
                if t and t.type=='DELIM' and t.value=='*':
                    # could be *| handled above; plain universal
                    comps.append(('type',None,'*')); self.next(); first=False; continue
                if t and t.type=='DELIM' and t.value=='&':
                    comps.append(('nesting',)); self.next(); first=False; continue
            else:
                if t and t.type=='DELIM' and t.value=='&':
                    comps.append(('nesting',)); self.next(); continue
            t=self.peek()
            if t is None: break
            if t.type=='HASH':
                comps.append(('id',t.value)); self.next(); first=False; continue
            if t.type=='DELIM' and t.value=='.':
                self.next(); nt=self.peek()
                if nt is None:
                    self.err("EndOfInput","Unexpected end of input",t,col=t.end_col+1)
                if nt.type!='IDENT':
                    raise ParseError(f"SelectorError(ClassNeedsIdent({token_debug(nt)}))", f"Expected identifier in class selector, got {token_debug(nt)}", self.source, nt.line, nt.end_col)
                comps.append(('class',nt.value)); self.next(); first=False; continue
            if t.type=='LBRACK':
                comps.append(self.parse_attr()); first=False; continue
            if t.type=='COLON':
                pc, is_elem = self.parse_pseudo()
                if is_elem: pseudo_element_seen=True
                comps.append(pc); first=False; continue
            break
        return comps
    def parse_attr(self):
        lb=self.next()  # [
        # namespace
        ns=False
        t=self.peek(); t2=self.peek(1)
        if t and t2 and t2.type=='DELIM' and t2.value=='|' and not (self.peek(2) and self.peek(2).type=='DELIM' and self.peek(2).value=='='):
            if t.type=='IDENT' or (t.type=='DELIM' and t.value=='*'):
                ns=t.value; self.next(); self.next()
        elif t and t.type=='DELIM' and t.value=='|' and t2 and t2.type=='IDENT':
            ns=''; self.next()
        t=self.peek()
        if t is None:
            self.err("EndOfInput","Unexpected end of input",lb)
        if t.type!='IDENT':
            raise ParseError(f"SelectorError(NoQualifiedNameInAttributeSelector({token_debug(t)}))", f"No qualified name in attribute selector: {token_debug(t)}.", self.source, t.line, t.end_col)
        name=t.value; self.next()
        t=self.peek()
        if t and t.type=='RBRACK':
            self.next(); return ('attr', ns if ns is not False else None, name, None, None, None)
        # operator
        op=None
        if t and t.type=='DELIM' and t.value=='=':
            op='='; self.next()
        elif t and t.type=='DELIM' and t.value in '~|^$*':
            opch=t.value; self.next(); t=self.peek()
            if t and t.type=='DELIM' and t.value=='=':
                op=opch+'='; self.next()
            else:
                self.err("EndOfInput","Unexpected end of input",t if t else lb)
        else:
            if t is None: self.err("EndOfInput","Unexpected end of input",lb)
            raise ParseError(f"SelectorError(UnexpectedTokenInAttributeSelector({token_debug(t)}))", f"Unexpected token in attribute selector: {token_debug(t)}", self.source, t.line, t.end_col)
        # value
        t=self.peek()
        if t is None:
            self.err("EndOfInput","Unexpected end of input",lb)
        if t.type=='RBRACK':
            raise ParseError("EndOfInput","Unexpected end of input",self.source,t.line,t.end_col)
        if t.type=='IDENT': val=t.value; self.next()
        elif t.type=='STRING': val=t.value; self.next()
        else:
            raise ParseError(f"SelectorError(BadValueInAttr({token_debug(t)}))", f"Invalid value in attribute selector: {token_debug(t)}", self.source, t.line, t.col+1)
        mod=None
        t=self.peek()
        if t and t.type=='IDENT':
            mod=t.value.lower(); self.next(); t=self.peek()
        if t and t.type=='RBRACK':
            self.next()
        elif t is None:
            self.err("EndOfInput","Unexpected end of input",lb)
        else:
            raise ParseError(f"SelectorError(UnexpectedTokenInAttributeSelector({token_debug(t)}))", f"Unexpected token in attribute selector: {token_debug(t)}", self.source, t.line, t.end_col)
        return ('attr', ns if ns is not False else None, name, op, val, mod)
    def parse_pseudo(self):
        colon=self.next()
        is_element=False
        t=self.peek()
        if t and t.type=='COLON':
            is_element=True; self.next(); t=self.peek()
        if t is None:
            # pseudo expected ident -> EndOfInput at brace (after prelude). caller token toks don't include brace; approximate colon end+1
            raise ParseError("EndOfInput","Unexpected end of input",self.source,colon.line,colon.end_col+2 if is_element else colon.end_col+1)
        if t.type=='IDENT':
            name=t.value; name_tok=t; self.next()
            self.warn_pseudo(name,is_element,name_tok,col=name_tok.col+1)
            return (('pseudo',name.lower(),is_element,None), is_element or name.lower() in ('before','after','first-line','first-letter'))
        if t.type=='FUNCTION':
            fname=t.value; ftok=t; self.next()
            self.warn_pseudo(fname,is_element,ftok,col=ftok.end_col+1)
            # collect tokens until matching RPAREN
            depth=1; inner=[]
            while True:
                tt=self.next()
                if tt is None: break
                if tt.type in ('FUNCTION','LPAREN'): depth+=1; inner.append(tt)
                elif tt.type=='RPAREN':
                    depth-=1
                    if depth==0: break
                    inner.append(tt)
                else: inner.append(tt)
            lname=fname.lower()
            arg=self.parse_pseudo_arg(lname,inner,is_element,ftok)
            return (('pseudo',lname,is_element,arg), is_element or lname in ('before','after','first-line','first-letter'))
        # unexpected token after colon (e.g. pseudo element expected ident)
        if is_element:
            raise ParseError(f"SelectorError(PseudoElementExpectedIdent({token_debug(t)}))", f"Expected identifier in pseudo element, got {token_debug(t)}", self.source, t.line, t.end_col)
        raise ParseError(f"SelectorError(PseudoClassExpectedIdent({token_debug(t)}))", f"Expected identifier in pseudo class, got {token_debug(t)}", self.source, t.line, t.end_col)
    def parse_pseudo_arg(self,lname,inner,is_element,ftok):
        # inner tokens (WS stripped in self.toks subset, but these come from same filtered list)
        if lname.startswith('nth-') or lname in ('nth-child','nth-last-child','nth-of-type','nth-last-of-type'):
            return self.parse_nth(inner)
        if lname in ('is','where','not','has','matches','-webkit-any','-moz-any','global','local'):
            sub=SelectorParser(inner,self.source,self.ox,nested=self.nested,allow_relative=(lname=='has'),parent_parser=self)
            # inner tokens need WS info lost? They are from filtered toks which retain space_before attributes per token object.
            return ('selectorlist', sub.parse_list())
        if lname in ('host','host-context','slotted'):
            sub=SelectorParser(inner,self.source,self.ox)
            # parse a single compound
            comp=sub.parse_compound()
            return ('compound',comp)
        if lname=='lang':
            vals=[]
            for tt in inner:
                if tt.type in ('IDENT','STRING'): vals.append(tt.value)
            return ('lang',vals)
        if lname=='dir':
            vals=[tt.value for tt in inner if tt.type=='IDENT']
            return ('ident', vals[0].lower() if vals else '')
        if lname in ('part','state'):
            vals=[]
            for tt in inner:
                if tt.type in ('IDENT','STRING'): vals.append(tt.value)
                elif tt.type=='DELIM' and tt.value=='-': vals.append('-')
            return ('idents',vals)
        # generic tokens
        comps,_=build_components(inner)
        return ('tokens',comps)
    def parse_nth(self,inner):
        # return (a,b, selectors or None)
        toks=list(inner)
        # split 'of'
        of_idx=None; depth=0
        for idx,tt in enumerate(toks):
            if tt.type in ('FUNCTION','LPAREN','LBRACK'): depth+=1
            elif tt.type in ('RPAREN','RBRACK'): depth-=1
            elif depth==0 and tt.type=='IDENT' and tt.value.lower()=='of' and idx>0:
                of_idx=idx; break
        sels=None
        if of_idx is not None:
            sel_toks=toks[of_idx+1:]; toks=toks[:of_idx]
            sub=SelectorParser(sel_toks,self.source,self.ox)
            sels=sub.parse_list()
        a,b=parse_anb(toks,self)
        return ('nth',a,b,sels)

def parse_anb(toks, parser):
    # toks filtered
    if not toks:
        raise ParseError("EndOfInput","Unexpected end of input",parser.source,0,1)
    def unexpected(t):
        raise ParseError(f"UnexpectedToken({token_debug(t)})", f"Unexpected token {token_debug(t)}", parser.source, t.line, t.col)
    i=0
    def peek():
        return toks[i] if i<len(toks) else None
    t=peek()
    a=0; b=0
    # odd/even/n
    if t.type=='IDENT':
        lv=t.value.lower()
        if lv=='odd': return (2,1) if len(toks)==1 else unexpected(toks[1])
        if lv=='even': return (2,0) if len(toks)==1 else unexpected(toks[1])
        if lv=='n': a=1; i+=1
        elif lv=='-n': a=-1; i+=1
        else: unexpected(t)
    elif t.type=='NUMBER':
        if t.extra and t.extra.get('int_value') is not None:
            if len(toks)==1: return (0, t.extra['int_value'])
            unexpected(toks[1])
        unexpected(t)
    elif t.type=='DIM':
        val,unit=t.value
        if t.extra and t.extra.get('int_value') is not None:
            iv=t.extra['int_value']
        else:
            unexpected(t)
        ul=unit.lower()
        if ul=='n': a=iv; i+=1
        elif ul.startswith('n-') and ul[2:].isdigit():
            return (iv, -int(ul[2:]))
        elif ul.startswith('n+') and ul[2:].isdigit():
            return (iv, int(ul[2:]))
        elif ul.startswith('-n'):
            unexpected(t)
        else:
            # e.g. 2x -> error on dimension? Reference UnexpectedToken Ident("x") for :nth-child(2x) because tokenizer? Wait 2x is dimension unit x. They error Ident x because parser consumed number and then expected... simulate:
            # Create pseudo ident token error at position of unit start
            fake=Token('IDENT',unit,t.start+len(str(abs(int(val)))) if False else t.start, t.end, t.line, t.col, t.end_col)
            # col of unit: token raw.find unit case-insensitively
            raw=t.raw; pos=raw.lower().find(unit.lower())
            col=t.col+(pos if pos>=0 else 1)
            raise ParseError(f"UnexpectedToken(Ident({rust_debug_str(unit)}))", f"Unexpected token Ident({rust_debug_str(unit)})", parser.source, t.line, col)
    elif t.type=='DELIM' and t.value in '+-':
        sign=-1 if t.value=='-' else 1; i+=1
        t=peek()
        if t is None: raise ParseError("EndOfInput","Unexpected end of input",parser.source,0,1)
        if t.type=='IDENT' and t.value.lower()=='n': a=sign; i+=1
        elif t.type=='DIM':
            val,unit=t.value; iv=t.extra.get('int_value') if t.extra else None
            if iv is None: unexpected(t)
            if unit.lower()=='n': a=sign*iv; i+=1
            elif unit.lower().startswith('n-') : return (sign*iv, -int(unit[2:]))
            elif unit.lower().startswith('n+'): return (sign*iv, int(unit[2:]))
            else: unexpected(t)
        elif t.type=='NUMBER' and t.extra and t.extra.get('int_value') is not None:
            return (0, sign*t.extra['int_value'])
        else: unexpected(t)
    else:
        unexpected(t)
    if i>=len(toks): return (a,0)
    t=toks[i]
    if t.type=='DELIM' and t.value in '+-':
        sign=-1 if t.value=='-' else 1; i+=1
        if i>=len(toks): raise ParseError("EndOfInput","Unexpected end of input",parser.source,t.line,t.end_col)
        nt=toks[i]
        if nt.type=='NUMBER' and nt.extra and nt.extra.get('int_value') is not None:
            return (a, sign*nt.extra['int_value'])
        unexpected(nt)
    unexpected(t)

def format_anb(a,b):
    if a==2 and b==1: return 'odd'
    if a==0: return str(b)
    if a==1: s='n'
    elif a==-1: s='-n'
    else: s=f"{a}n"
    if b>0: s+=f"+{b}"
    elif b<0: s+=f"-{abs(b)}"
    return s

def selector_to_text(sels, ox):
    return (', ' if not ox.minify else ',').join(complex_to_text(s,ox) for s in sels)

def complex_to_text(parts, ox):
    out=""
    for idx,(comb,compound) in enumerate(parts):
        comp_text=''.join(comp_to_selector_text(c,ox) for c in compound)
        if idx==0:
            if comb:
                if comb in '>+~': out+= (comb+'' if ox.minify else comb+' ') if False else (f"{comb} " if not ox.minify else f"{comb}")
                elif comb=='||': out+= ('|| ' if not ox.minify else '||')
                elif comb==' ': out+=' '
            out+=comp_text
        else:
            if comb==' ' or comb is None: out+=' '+comp_text
            elif comb=='||': out+=(' || ' if not ox.minify else '||')+comp_text
            else: out+=((f' {comb} ' if not ox.minify else f'{comb}')+comp_text)
    return out

def comp_to_selector_text(c, ox):
    kind=c[0]
    if kind=='type':
        _,ns,name=c
        nsp = (ns+'|') if ns not in (None,'') else ('|' if ns=='' else '')
        return nsp + (name if name=='*' else (serialize_ident(name) if needs_escape(name) else name))
    if kind=='nesting': return '&'
    if kind=='class': return '.'+serialize_ident(c[1])
    if kind=='id': return '#'+serialize_ident(c[1])
    if kind=='attr':
        _,ns,name,op,val,mod=c
        s='['
        if ns not in (None,''): s+=ns+'|'
        s+= (serialize_ident(name) if needs_escape(name) else name)
        if op:
            s+=op
            if not ox.minify or ns not in (None,''):
                s+=serialize_string(val)
            else:
                if val=='':
                    s+=serialize_string(val)
                else:
                    idt=serialize_ident(val); st=serialize_string(val)
                    s+= idt if len(idt)<len(st) else st
            if mod: s+=' '+mod
        s+=']'
        return s
    if kind=='pseudo':
        _,name,is_elem,arg=c
        legacy={'before','after','first-line','first-letter'}
        if name in legacy:
            prefix=':'
        else:
            prefix='::' if is_elem else ':'
        if arg is None:
            return prefix+name
        # arg tuple
        ak=arg[0]
        if ak=='nth':
            _,a,b,sels=arg
            # first/last conversion handled in pseudo text generation at higher? do here based on name
            if a==0 and b==1 and not sels:
                mp={'nth-child':'first-child','nth-last-child':'last-child','nth-of-type':'first-of-type','nth-last-of-type':'last-of-type'}
                if name in mp: return ':'+mp[name]
            inside=format_anb(a,b)
