    if not toks:
        raise ParseError("EndOfInput","Unexpected end of input",parser.source,0,1)
    def unexpected(t):
        raise ParseError(f"UnexpectedToken({token_debug(t)})", f"Unexpected token {token_debug(t)}", parser.source, t.line, t.col)
    i=0
    def peek():
        return toks[i] if i<len(toks) else None
    t=peek()
    a=0; b=0
    # odd/even/n
    if t.type=='IDENT':
        lv=t.value.lower()
        if lv=='odd': return (2,1) if len(toks)==1 else unexpected(toks[1])
        if lv=='even': return (2,0) if len(toks)==1 else unexpected(toks[1])
        if lv=='n': a=1; i+=1
        elif lv=='-n': a=-1; i+=1
        else: unexpected(t)
    elif t.type=='NUMBER':
        if t.extra and t.extra.get('int_value') is not None:
            if len(toks)==1: return (0, t.extra['int_value'])
            unexpected(toks[1])
        unexpected(t)
    elif t.type=='DIM':
        val,unit=t.value
        if t.extra and t.extra.get('int_value') is not None:
            iv=t.extra['int_value']
        else:
            unexpected(t)
        ul=unit.lower()
        if ul=='n': a=iv; i+=1
        elif ul.startswith('n-') and ul[2:].isdigit():
            return (iv, -int(ul[2:]))
        elif ul.startswith('n+') and ul[2:].isdigit():
            return (iv, int(ul[2:]))
        elif ul.startswith('-n'):
            unexpected(t)
        else:
            # e.g. 2x -> error on dimension? Reference UnexpectedToken Ident("x") for :nth-child(2x) because tokenizer? Wait 2x is dimension unit x. They error Ident x because parser consumed number and then expected... simulate:
            # Create pseudo ident token error at position of unit start
            fake=Token('IDENT',unit,t.start+len(str(abs(int(val)))) if False else t.start, t.end, t.line, t.col, t.end_col)
            # col of unit: token raw.find unit case-insensitively
            raw=t.raw; pos=raw.lower().find(unit.lower())
            col=t.col+(pos if pos>=0 else 1)
            raise ParseError(f"UnexpectedToken(Ident({rust_debug_str(unit)}))", f"Unexpected token Ident({rust_debug_str(unit)})", parser.source, t.line, col)
    elif t.type=='DELIM' and t.value in '+-':
        sign=-1 if t.value=='-' else 1; i+=1
        t=peek()
        if t is None: raise ParseError("EndOfInput","Unexpected end of input",parser.source,0,1)
        if t.type=='IDENT' and t.value.lower()=='n': a=sign; i+=1
        elif t.type=='DIM':
            val,unit=t.value; iv=t.extra.get('int_value') if t.extra else None
            if iv is None: unexpected(t)
            if unit.lower()=='n': a=sign*iv; i+=1
            elif unit.lower().startswith('n-') : return (sign*iv, -int(unit[2:]))
            elif unit.lower().startswith('n+'): return (sign*iv, int(unit[2:]))
            else: unexpected(t)
        elif t.type=='NUMBER' and t.extra and t.extra.get('int_value') is not None:
            return (0, sign*t.extra['int_value'])
        else: unexpected(t)
    else:
        unexpected(t)
    if i>=len(toks): return (a,0)
    t=toks[i]
    if t.type=='DELIM' and t.value in '+-':
        sign=-1 if t.value=='-' else 1; i+=1
        if i>=len(toks): raise ParseError("EndOfInput","Unexpected end of input",parser.source,t.line,t.end_col)
        nt=toks[i]
        if nt.type=='NUMBER' and nt.extra and nt.extra.get('int_value') is not None:
            return (a, sign*nt.extra['int_value'])
        unexpected(nt)
    unexpected(t)

def format_anb(a,b):
    if a==2 and b==1: return 'odd'
    if a==0: return str(b)
    if a==1: s='n'
    elif a==-1: s='-n'
    else: s=f"{a}n"
    if b>0: s+=f"+{b}"
    elif b<0: s+=f"-{abs(b)}"
    return s

def selector_to_text(sels, ox):
    return (', ' if not ox.minify else ',').join(complex_to_text(s,ox) for s in sels)

def complex_to_text(parts, ox):
    out=""
    for idx,(comb,compound) in enumerate(parts):
        comp_text=''.join(comp_to_selector_text(c,ox) for c in compound)
        if idx==0:
            if comb:
                if comb in '>+~': out+= (comb+'' if ox.minify else comb+' ') if False else (f"{comb} " if not ox.minify else f"{comb}")
                elif comb=='||': out+= ('|| ' if not ox.minify else '||')
                elif comb==' ': out+=' '
            out+=comp_text
        else:
            if comb==' ' or comb is None: out+=' '+comp_text
            elif comb=='||': out+=(' || ' if not ox.minify else '||')+comp_text
            else: out+=((f' {comb} ' if not ox.minify else f'{comb}')+comp_text)
    return out

def comp_to_selector_text(c, ox):
    kind=c[0]
    if kind=='type':
        _,ns,name=c
        nsp = (ns+'|') if ns not in (None,'') else ('|' if ns=='' else '')
        return nsp + (name if name=='*' else (serialize_ident(name) if needs_escape(name) else name))
    if kind=='nesting': return '&'
    if kind=='class': return '.'+serialize_ident(c[1])
    if kind=='id': return '#'+serialize_ident(c[1])
    if kind=='attr':
        _,ns,name,op,val,mod=c
        s='['
        if ns not in (None,''): s+=ns+'|'
        s+= (serialize_ident(name) if needs_escape(name) else name)
        if op:
            s+=op
            if not ox.minify or ns not in (None,''):
                s+=serialize_string(val)
            else:
                if val=='':
                    s+=serialize_string(val)
                else:
                    idt=serialize_ident(val); st=serialize_string(val)
                    s+= idt if len(idt)<len(st) else st
            if mod: s+=' '+mod
        s+=']'
        return s
    if kind=='pseudo':
        _,name,is_elem,arg=c
        legacy={'before','after','first-line','first-letter'}
        if name in legacy:
            prefix=':'
        else:
            prefix='::' if is_elem else ':'
        if arg is None:
            return prefix+name
        # arg tuple
        ak=arg[0]
        if ak=='nth':
            _,a,b,sels=arg
            # first/last conversion handled in pseudo text generation at higher? do here based on name
            if a==0 and b==1 and not sels:
                mp={'nth-child':'first-child','nth-last-child':'last-child','nth-of-type':'first-of-type','nth-last-of-type':'last-of-type'}
                if name in mp: return ':'+mp[name]
            inside=format_anb(a,b)
            if sels: inside+= ' of ' + selector_to_text(sels,ox)
            return f"{prefix}{name}({inside})"
        if ak=='selectorlist':
            if name=='matches':
                inside=', '.join(complex_to_text(s,ox) for s in arg[1])
            else:
                inside=selector_to_text(arg[1],ox)
            return f"{prefix}{name}({inside})"
        if ak=='compound':
            inside=''.join(comp_to_selector_text(x,ox) for x in arg[1])
            return f"{prefix}{name}({inside})"
        if ak=='lang':
            inside=(', ' if not ox.minify else ',').join(serialize_ident(v) for v in arg[1])
            return f"{prefix}{name}({inside})"
        if ak=='ident':
            return f"{prefix}{name}({arg[1]})"
        if ak=='idents':
            inside=' '.join(serialize_ident(v) if needs_escape(v) else v for v in arg[1])
            return f"{prefix}{name}({inside})"
        if ak=='tokens':
            inside=comps_to_text_typed(arg[1],ox,lower_idents=False)
            # generic pseudo tokens: commas have no following space in pretty observed (:foo(1,2))
            # comps_to_text_typed adds space after comma in pretty; remove it
            if not ox.minify:
                inside=inside.replace(', ', ',')
            return f"{prefix}{name}({inside})"
    return ''

