def normalize_feature(name_l):
    # returns (prefix_vendor, op, base)
    vendor=''
    rest=name_l
    for vp in ('-webkit-','-moz-','-ms-','-o-'):
        if rest.startswith(vp): vendor=vp; rest=rest[len(vp):]; break
    op=None
    if rest.startswith('min-'): op='>='; rest=rest[4:]
    elif rest.startswith('max-'): op='<='; rest=rest[4:]
    return vendor,op,rest

class MediaList:
    def __init__(self,queries,raw_invalid=None): self.queries=queries; self.raw_invalid=raw_invalid
    def to_text(self,ox, legacy=False):
        return (', ' if not ox.minify else ',').join(q.to_text(ox,legacy) for q in self.queries)

class MediaQuery:
    def __init__(self, modifier=None, mtype=None, conditions=None, raw=None):
        self.modifier=modifier; self.mtype=mtype; self.conditions=conditions or []; self.raw=raw
    def to_text(self,ox,legacy=False):
        if self.raw is not None: return self.raw
        parts=[]
        if self.modifier: parts.append(self.modifier)
        if self.mtype: parts.append(self.mtype)
        cond_text=' and '.join(c.to_text(ox,legacy) if hasattr(c,'to_text') else str(c) for c in self.conditions)
        if cond_text:
