    # kind: feature / range / group / not / custom
    def __init__(self,kind,name=None,value=None,op=None,children=None,connector=None,value2=None,op2=None):
        self.kind=kind; self.name=name; self.value=value; self.op=op; self.children=children or []; self.connector=connector; self.value2=value2; self.op2=op2
    def to_text(self,ox,legacy=False):
        sp=' ' if not ox.minify else ''
        if self.kind=='custom':
            return f"({self.name})"
        if self.kind=='bool':
            return f"({self.name})"
        if self.kind=='plain':
            colon=': ' if not ox.minify else ':'
            return f"({self.name}{colon}{self.value})"
        if self.kind=='range':
            if legacy:
