    def err_end(self, tok=None):
        if tok is not None:
            return ParseError("EndOfInput","Unexpected end of input",self.source,tok.line,tok.end_col)
        ln,cl=self.source.eof_loc(); return ParseError("EndOfInput","Unexpected end of input",self.source,ln,cl)
    def unexpected(self,tok,col=None):
        if tok.type in ('DELIM','SEMI','RBRACE','COLON','COMMA','RPAREN','RBRACK'):
            c=tok.end_col
        else:
            c=tok.col
        if col is not None: c=col
        return ParseError(f"UnexpectedToken({token_debug(tok)})", f"Unexpected token {token_debug(tok)}", self.source, tok.line, c)
    def log_error(self,e):
        sys.stderr.write(e.friendly_line())
    def find_block(self,i,end):
        # toks[i] is LBRACE; return (inner_start,inner_end,next_index,closed)
        depth=0; j=i
        while j<end:
            ty=self.toks[j].type
            if ty=='LBRACE': depth+=1
            elif ty=='RBRACE':
                depth-=1
                if depth==0:
                    return (i+1,j,j+1,True)
            j+=1
        return (i+1,end,end,False)
    def scan_prelude(self,i,end,is_at):
        # returns (prelude_end, terminator, terminator_index) terminator in 'brace','semi','eof'
        depth=0; brack=0; j=i
        while j<end:
            t=self.toks[j]; ty=t.type
            if ty in ('FUNCTION','LPAREN'): depth+=1
            elif ty=='RPAREN': depth=max(0,depth-1)
            elif ty=='LBRACK': brack+=1
            elif ty=='RBRACK': brack=max(0,brack-1)
            elif depth==0 and brack==0 and ty=='LBRACE':
                return (j,'brace',j)
            elif is_at and depth==0 and brack==0 and ty=='SEMI':
                return (j,'semi',j)
            j+=1
        return (end,'eof',end)
    def parse_stylesheet(self):
        rules, license_comments = self.parse_rule_list(0,len(self.toks), top=True)
        return Node('stylesheet',data={'license':license_comments},rules=rules)
    def parse_rule_list(self,start,end,top=False,context='normal'):
        rules=[]; license_comments=[]
        seen_non_import=False
        i=start
        # license comments only top at very beginning
        if top:
            j=i
            comments=[]
            while j<end:
                t=self.toks[j]
                if t.type in ('WS',): j+=1; continue
                if t.type=='COMMENT':
                    if t.value.startswith('!'): comments.append(t.value)
                    j+=1; continue
                if t.type in ('CDO','CDC'): j+=1; continue
                break
            license_comments=comments
            # do not advance i globally here; rules parsing will skip comments
        while True:
            # skip ignorables
            while i<end and self.toks[i].type in ('WS','COMMENT','CDO','CDC'): i+=1
            if i>=end: break
            start_i=i
            try:
                node, i, is_importish = self.parse_one_rule(i,end,top,seen_non_import,context)
            except ParseError as e:
                if not self.ox.error_recovery:
                    raise
                self.log_error(e)
                # recovery: skip this rule. parse_one_rule scanning is determined: try rescan to find its block/statement end from start_i
                i=self.skip_rule(start_i,end)
                continue
            if node is not None:
                rules.append(node)
            if top:
                if is_importish:
                    pass
                else:
                    # a statement @layer handled as importish True; charset node None also importish
                    if node is not None or True:
                        # parse_one_rule returns is_importish for charset/import/layer stmt
                        seen_non_import=True if not is_importish else seen_non_import
