            _,_,nxt,_=self.find_block(ti,end); return nxt
        if term=='semi': return ti+1
        return end
    def parse_one_rule(self,i,end,top,seen_non_import,context):
        t=self.toks[i]
        if t.type=='AT':
            return self.parse_at_rule(i,end,top,seen_non_import,context)
        else:
            # qualified rule
            pe,term,ti=self.scan_prelude(i,end,False)
            if term!='brace':
                raise self.err_end()
