            boundary=self.scan_style_item(i,end)
            if boundary[0]=='nested':
                _,pe,ti=boundary; start_i=i
                bs,be,nxt,_=self.find_block(ti,end)
                prelude=self.toks[i:pe]
                self.check_bad_tokens(prelude)
                try:
                    sp=SelectorParser(prelude,self.source,self.ox,nested=True)
                    sels=sp.parse_list()
                    sels=apply_implicit_nesting(sels)
                except ParseError as e:
                    if 'DanglingCombinator' in e.kind:
                        brace=self.toks[ti]; e.col=brace.end_col; e.line=brace.line
                    if not self.ox.error_recovery: raise
                    self.log_error(e); i=nxt; continue
                d2,n2=self.parse_style_block(bs,be)
                nested.append(Node('style',loc=self.loc(t),data={'selectors':sels},decls=d2,rules=n2))
                i=nxt; continue
            else:
                _,seg_end,term,ti=boundary
                seg=self.toks[i:seg_end]
                try:
                    d=self.parse_declaration(seg,terminator=term,term_tok=(self.toks[ti] if ti is not None and ti<end else None))
                    if d is not None:
                        d.order=order; order+=1; decls.append(d)
                except ParseError as e:
                    if self.ox.error_recovery and term=='semi':
                        # speculative pseudo warning
                        self.maybe_spec_pseudo_warning(seg)
                        self.log_error(e)
                    else:
                        raise
