    def maybe_spec_pseudo_warning(self,seg):
        # if seg is IDENT COLON ident/function where ident is unknown pseudo class, emit warning
        mu=[t for t in seg if t.type not in ('WS','COMMENT')]
        if len(mu)>=3 and mu[0].type=='IDENT' and mu[1].type=='COLON':
            t=mu[2]
            if t.type=='IDENT':
                name=t.value
                if name.lower() not in KNOWN_PSEUDO_CLASSES and not name.startswith('-'):
                    sys.stderr.write(f"'{name}' is not recognized as a valid pseudo-class. Did you mean '::{name}' (pseudo-element) or is this a typo? at {self.source.filename}:{t.line}:{t.col+1}\n")
            elif t.type=='FUNCTION':
                name=t.value
                if name.lower() not in KNOWN_PSEUDO_CLASSES and not name.startswith('-'):
                    sys.stderr.write(f"'{name}' is not recognized as a valid pseudo-class. Did you mean '::{name}' (pseudo-element) or is this a typo? at {self.source.filename}:{t.line}:{t.end_col+1}\n")
        elif len(mu)>=2 and mu[0].type=='COLON':
            t=mu[1]
            if t.type=='IDENT':
                name=t.value
                if name.lower() not in KNOWN_PSEUDO_CLASSES and not name.startswith('-'):
                    sys.stderr.write(f"'{name}' is not recognized as a valid pseudo-class. Did you mean '::{name}' (pseudo-element) or is this a typo? at {self.source.filename}:{t.line}:{t.col+1}\n")
    def scan_style_item(self,i,end):
        depth=0; brack=0; j=i; brace_depth=0
        # Determine custom prop header quickly
        mu_idx=[]
        while j<end:
            t=self.toks[j]; ty=t.type
            if ty in ('FUNCTION','LPAREN'): depth+=1
            elif ty=='RPAREN': depth=max(0,depth-1)
            elif ty=='LBRACK': brack+=1
            elif ty=='RBRACK': brack=max(0,brack-1)
            elif depth==0 and brack==0:
                if ty=='LBRACE':
                    if self._is_custom_decl_header(i,j):
                        brace_depth+=1; j+=1; continue
                    return ('nested',j,j)
                if ty=='RBRACE':
                    if brace_depth>0: brace_depth-=1; j+=1; continue
                    return ('decl',j,'end',j)
                if ty=='SEMI' and brace_depth==0:
                    return ('decl',j,'semi',j)
            else:
                if ty=='LBRACE': brace_depth+=1
                elif ty=='RBRACE' and brace_depth>0: brace_depth-=1
            j+=1
