        if first.type=='IDENT':
            if len(mu)==1:
                # EndOfInput at after semi or block brace
                if term_tok is not None:
                    raise ParseError("EndOfInput","Unexpected end of input",self.source,term_tok.line,term_tok.end_col)
                raise ParseError("EndOfInput","Unexpected end of input",self.source,first.line,first.end_col+1)
            second=mu[1]
            if second.type!='COLON':
                raise self.unexpected(second)
            # good
            name=first.value
            # value tokens in seg after colon token position
            colon_pos=seg.index(second)
            val_toks=seg[colon_pos+1:]
            important, val_toks2, err = self.extract_important(val_toks, name)
            if err: raise err
            comps,_=build_components(val_toks2)
            is_custom=name.startswith('--')
            dname=name if is_custom else name.lower()
            return Decl(name=dname, comps=comps, important=important, loc=self.loc(first), is_custom=is_custom)
