        last=mu[-1]
        # term_tok may be RBRACE token from enclosing? In scan_style_item end case term_tok None. Use source eof-ish: find token after seg in full toks if possible
        try:
            idx=self.toks.index(last)
            nxt=self.toks[idx+1] if idx+1<len(self.toks) else None
            if nxt and nxt.type=='RBRACE':
                raise ParseError("EndOfInput","Unexpected end of input",self.source,nxt.line,nxt.end_col)
        except ValueError:
            pass
        raise ParseError("EndOfInput","Unexpected end of input",self.source,last.line,last.end_col+1)
    def extract_important(self,val_toks, prop_name):
        # find top-level DELIM '!'
        depth=0; brack=0; brace=0
        bangs=[]
        for idx,t in enumerate(val_toks):
            ty=t.type
            if ty in ('FUNCTION','LPAREN'): depth+=1
            elif ty=='RPAREN': depth=max(0,depth-1)
            elif ty=='LBRACK': brack+=1
            elif ty=='RBRACK': brack=max(0,brack-1)
            elif ty=='LBRACE': brace+=1
            elif ty=='RBRACE': brace=max(0,brace-1)
            elif depth==0 and brack==0 and brace==0 and ty=='DELIM' and t.value=='!':
