            bi=bangs[0]
            after=[t for t in val_toks[bi+1:] if t.type not in ('WS','COMMENT')]
            if len(bangs)==1 and len(after)==1 and after[0].type=='IDENT' and after[0].value.lower()=='important':
                return True,val_toks[:bi],None
            return False,val_toks,None
        bi=bangs[0]; bang_tok=val_toks[bi]
        after=[t for t in val_toks[bi+1:] if t.type not in ('WS','COMMENT')]
