    # descriptor declarations (@font-face etc)
    def parse_descriptor_block(self,start,end):
        decls=[]; i=start; order=0
        while True:
            while i<end and self.toks[i].type in ('WS','COMMENT','SEMI'): i+=1
            if i>=end: break
            # segment to semi or end
