                if d: d.order=order; order+=1; decls.append(d)
            i=j+1 if j<end else end
        return decls

def apply_implicit_nesting(sels):
    out=[]
    for parts in sels:
        text_has_nesting=any(c[0]=='nesting' for _,comp in parts for c in comp)
        if text_has_nesting:
