        elif first_comp and first_comp[0][0]=='pseudo':
            # :hover -> &:hover
            out.append([(None, [('nesting',)]+first_comp)]+parts[1:])
        else:
            # descendant & <sel>
            out.append([(None,[('nesting',)]),(' ',first_comp)]+parts[1:])
    return out

