def apply_implicit_nesting(sels):
    out=[]
    for parts in sels:
        text_has_nesting=any(c[0]=='nesting' for _,comp in parts for c in comp)
        if text_has_nesting:
            out.append(parts); continue
        if not parts:
            out.append(parts); continue
        first_comb, first_comp = parts[0]
        if first_comb in ('>','+','~','||'):
            out.append([(None,[('nesting',)]),(first_comb,first_comp)]+parts[1:])
        elif first_comp and first_comp[0][0]=='pseudo':
            # :hover -> &:hover
            out.append([(None, [('nesting',)]+first_comp)]+parts[1:])
        else:
            # descendant & <sel>
            out.append([(None,[('nesting',)]),(' ',first_comp)]+parts[1:])
    return out

