def _parser_parse_import(self,at_tok,prelude_comps,prelude_toks,term,ti,loc):
    mu=meaningful(prelude_comps)
    if not mu:
        if term=='semi':
            t=self.toks[ti]; raise ParseError("EndOfInput","Unexpected end of input",self.source,t.line,t.end_col-0)
        raise ParseError("EndOfInput","Unexpected end of input",self.source,at_tok.line,at_tok.end_col+1)
    first=mu[0]; url=None
    if first.kind=='tok' and first.token.type in ('STRING','URL'):
        url=first.token.value
    elif first.kind=='func' and first.token.value.lower()=='url':
        mm=meaningful(first.children); url=str(mm[0].token.value) if mm else ''
    else:
        t=first.token
        raise self.unexpected(t, col=t.col)
    idx=1; supports=None; layer_marker=None; layer_name=None
    # supports(...)
    if idx<len(mu) and mu[idx].kind=='func' and mu[idx].token.value.lower()=='supports':
        supports=mu[idx]; idx+=1
    if idx<len(mu) and mu[idx].kind=='tok' and mu[idx].token.type=='IDENT' and mu[idx].token.value.lower()=='layer':
        layer_marker=True; idx+=1
        if idx<len(mu) and mu[idx].kind=='tok' and mu[idx].token.type=='IDENT':
            # layer name - but could be media type if it's e.g. screen? After layer, next ident is layer name unless followed by and/... Reference layer foo: name. If next ident is known media start and there are following tokens? Layer names are custom idents; treat as name.
            layer_name=mu[idx].token.value; idx+=1
        # if later supports fn -> error unexpected function if it appears as first of remaining media? Reference checks media parsing and functions unexpected.
        if idx<len(mu) and mu[idx].kind=='func':
            t=mu[idx].token
            raise ParseError(f"UnexpectedToken(Function({rust_debug_str(t.value)}))", f"Unexpected token Function({rust_debug_str(t.value)})", self.source, t.line, t.col)
    media=None
    if idx<len(mu):
        if mu[idx].kind=='func':
            t=mu[idx].token
            raise ParseError(f"UnexpectedToken(Function({rust_debug_str(t.value)}))", f"Unexpected token Function({rust_debug_str(t.value)})", self.source, t.line, t.col)
        media=parse_media_list_from_comps(mu[idx:],self.source,self.ox)
    supp_text=None
    if supports is not None:
        # supports children are a supports condition: could be (decl) stored as block or decl tokens
        # supports(display:grid): children comps are ident colon ident (declaration without parens in function)
        inner=meaningful(supports.children)
        if inner and inner[0].kind=='block':
            supp_text=supports_to_text(supports.children,self.ox)
        elif _looks_like_declaration(list(inner)):
            ci=next(i for i,x in enumerate(inner) if x.kind=='tok' and x.token.type=='COLON')
            prop=inner[0].token.value.lower(); val=comps_to_text_typed(inner[ci+1:],self.ox)
            colon=': ' if not self.ox.minify else ':'
            supp_text=f"({prop}{colon}{val})"
        else:
            supp_text='('+supports_to_text(supports.children,self.ox)+')'
            # For 'not (display:grid)' children include not/block => supports_to_text returns 'not (display: grid)' - wrap not needed? import prints supports(not (display: grid)) - handled in printer by enclosing? store inner without outer:
            supp_text=supports_to_text(supports.children,self.ox)
            # If supp_text starts with '(' it's a decl condition; keep as inner for supports(...)
            # We'll store a flag
            if supp_text.startswith('('):
                pass
        # Normalize: store canonical inside text for printer: if supp_text is '(prop: v)' printer prints supports(prop: v)? Actual reference: supports(display: grid) without extra parens around decl.
        # So strip a pair if it's a simple declaration paren we constructed.
        # Determine final inside:
        if inner and inner[0].kind!='block' and _looks_like_declaration(list(inner)):
            ci=next(i for i,x in enumerate(inner) if x.kind=='tok' and x.token.type=='COLON')
            prop=inner[0].token.value.lower(); val=comps_to_text_typed(inner[ci+1:],self.ox)
            colon=': ' if not self.ox.minify else ':'
            supp_text=f"{prop}{colon}{val}"
    return Node('import',loc=loc,data={'url':url,'layer':layer_marker,'layer_name':layer_name,'supports':supp_text,'supports_comp':supports,'media':media})

def _parser_parse_keyframes_block(self,start,end):
    frames=[]; i=start
    while True:
        while i<end and self.toks[i].type in ('WS','COMMENT','SEMI'): i+=1
        if i>=end: break
        pe,term,ti=self.scan_prelude(i,end,False)
        if term!='brace':
            break
        bs,be,nxt,_=self.find_block(ti,end)
        sel_toks=self.toks[i:pe]
        comps,_=build_components(sel_toks)
        parts=split_commas(comps)
        sels=[]; valid=True
        for p in parts:
            mm=meaningful(p)
            if len(mm)==1 and mm[0].kind=='tok':
                t=mm[0].token
                if t.type=='IDENT' and t.value.lower() in ('from','to'):
                    sels.append(t.value.lower()); continue
                if t.type=='PERCENT':
                    sels.append(fmt_num(t.value)+'%'); continue
            valid=False; break
        if valid and sels:
            decls,nested=self.parse_style_block(bs,be)
            frames.append(Node('keyframe',loc=self.loc(self.toks[i]),data={'selectors':sels},decls=decls,rules=nested))
        i=nxt
    return frames

def _parser_parse_page_block(self,start,end):
    decls=[]; rules=[]; i=start; order=0
    while True:
        while i<end and self.toks[i].type in ('WS','COMMENT','SEMI'): i+=1
        if i>=end: break
        t=self.toks[i]
        if t.type=='AT':
            # margin at-rule: parse generically as descriptor-ish node
            pe,term,ti=self.scan_prelude(i+1,end,True)
            if term=='brace':
                bs,be,nxt,_=self.find_block(ti,end)
                d=self.parse_descriptor_block(bs,be)
                rules.append(Node('page_margin',loc=self.loc(t),data={'name':t.value.lower()},decls=d)); i=nxt; continue
            else:
                i=ti+1 if term=='semi' else end; continue
        # declaration segment
        boundary=self.scan_style_item(i,end)
        if boundary[0]=='decl':
            _,seg_end,term,ti=boundary; seg=self.toks[i:seg_end]
            try:
                d=self.parse_declaration(seg,terminator=term,term_tok=self.toks[ti] if ti is not None and ti<end else None)
                if d: d.order=order; order+=1; decls.append(d)
            except ParseError:
                if not self.ox.error_recovery: raise
            i=ti+1 if term=='semi' else seg_end
        else:
            _,pe,ti=boundary; _,_,nxt,_=self.find_block(ti,end); i=nxt
    return decls,rules

Parser.parse_at_rule=_parser_parse_at_rule
Parser.parse_import=_parser_parse_import
