def _parser_parse_keyframes_block(self,start,end):
    frames=[]; i=start
    while True:
        while i<end and self.toks[i].type in ('WS','COMMENT','SEMI'): i+=1
        if i>=end: break
        pe,term,ti=self.scan_prelude(i,end,False)
        if term!='brace':
            break
        bs,be,nxt,_=self.find_block(ti,end)
        sel_toks=self.toks[i:pe]
        comps,_=build_components(sel_toks)
        parts=split_commas(comps)
        sels=[]; valid=True
        for p in parts:
            mm=meaningful(p)
            if len(mm)==1 and mm[0].kind=='tok':
                t=mm[0].token
                if t.type=='IDENT' and t.value.lower() in ('from','to'):
                    sels.append(t.value.lower()); continue
                if t.type=='PERCENT':
                    sels.append(fmt_num(t.value)+'%'); continue
            valid=False; break
        if valid and sels:
            decls,nested=self.parse_style_block(bs,be)
            frames.append(Node('keyframe',loc=self.loc(self.toks[i]),data={'selectors':sels},decls=decls,rules=nested))
        i=nxt
    return frames

def _parser_parse_page_block(self,start,end):
    decls=[]; rules=[]; i=start; order=0
    while True:
        while i<end and self.toks[i].type in ('WS','COMMENT','SEMI'): i+=1
        if i>=end: break
        t=self.toks[i]
        if t.type=='AT':
            # margin at-rule: parse generically as descriptor-ish node
            pe,term,ti=self.scan_prelude(i+1,end,True)
            if term=='brace':
                bs,be,nxt,_=self.find_block(ti,end)
                d=self.parse_descriptor_block(bs,be)
                rules.append(Node('page_margin',loc=self.loc(t),data={'name':t.value.lower()},decls=d)); i=nxt; continue
            else:
                i=ti+1 if term=='semi' else end; continue
        # declaration segment
        boundary=self.scan_style_item(i,end)
        if boundary[0]=='decl':
            _,seg_end,term,ti=boundary; seg=self.toks[i:seg_end]
            try:
                d=self.parse_declaration(seg,terminator=term,term_tok=self.toks[ti] if ti is not None and ti<end else None)
                if d: d.order=order; order+=1; decls.append(d)
            except ParseError:
                if not self.ox.error_recovery: raise
            i=ti+1 if term=='semi' else seg_end
        else:
            _,pe,ti=boundary; _,_,nxt,_=self.find_block(ti,end); i=nxt
    return decls,rules

Parser.parse_at_rule=_parser_parse_at_rule
Parser.parse_import=_parser_parse_import
Parser.parse_keyframes_block=_parser_parse_keyframes_block
Parser.parse_page_block=_parser_parse_page_block

