# font family
def process_font_family(comps,ox):
    parts=split_commas(comps); out=[]
    generic={'serif','sans-serif','monospace','cursive','fantasy','system-ui','ui-serif','ui-sans-serif','ui-monospace','ui-rounded','emoji','math','fangsong'}
    for part in parts:
        mu=meaningful(part)
        if len(mu)==1 and mu[0].kind=='tok' and mu[0].token.type=='STRING':
            s=mu[0].token.value
            words=s.split()
            if s.strip().lower() in generic:
                out.append(serialize_string(s)); continue
            if words and all(_is_family_ident_word(w) for w in words) and s.strip()==s and '  ' not in s:
                # avoid unquoting if single word is a CSS-wide/generic keyword?
                out.append(' '.join(words)); continue
            out.append(serialize_string(s)); continue
        # sequence idents; lower if generic single
        vals=[]
        for c in mu:
            if c.kind=='tok' and c.token.type=='IDENT':
                v=c.token.value
                if len(mu)==1 and v.lower() in generic: v=v.lower()
                vals.append(v)
            else: vals.append(comp_to_text_typed(c,ox))
        out.append(' '.join(vals))
    return (', ' if not ox.minify else ',').join(out)

def _is_family_ident_word(w):
    if not w: return False
    if not (is_ident_start_char(w[0]) or w[0]=='-'): return False
    return all(is_name_char(ch) for ch in w)

def process_font(comps,ox):
    mu=meaningful(comps)
    if len(mu)==1 and mu[0].kind=='tok' and mu[0].token.type=='IDENT':
        return mu[0].token.value.lower()
    # find slash
    slash_parts=split_top(comps,delim_value='/')
    line_height=None
    main_comps=comps
    if len(slash_parts)==2:
        # left part last comp is size; right first is line-height, rest family - but split_top split all--- right part contains lh+family
        right=meaningful(slash_parts[1])
        if right:
            line_height=comp_to_text_typed(right[0],ox)
            family_comps=right[1:]
            left=meaningful(slash_parts[0])
            return _font_text(left,line_height,family_comps,ox)
    left=meaningful(comps)
    return _font_text(left,None,None,ox)

def _font_text(left,line_height,family_comps,ox):
    # left includes optional pre keywords + size + (family if family_comps None)
    # find size: a dimension/percent/math or size keyword ident
    size_keywords={'xx-small','x-small','small','medium','large','x-large','xx-large','xxx-large','smaller','larger'}
    size_idx=None
    for i,c in enumerate(left):
        if c.kind=='tok' and c.token.type in ('DIM','PERCENT'):
            size_idx=i; break
        if c.kind=='func':
            size_idx=i; break
        if c.kind=='tok' and c.token.type=='IDENT' and c.token.value.lower() in size_keywords:
            size_idx=i; break
    if size_idx is None:
        return comps_to_text_typed(left,ox)
    pre=left[:size_idx]; size=comp_to_text_typed(left[size_idx],ox)
    style=None; variant=None; weight=None; stretch=None
    for c in pre:
        if c.kind!='tok': continue
        t=c.token
        if t.type=='IDENT':
            lv=t.value.lower()
            if lv in ('italic','oblique'): style=lv if not (lv=='oblique' and False) else lv
            elif lv=='small-caps': variant=lv
            elif lv in ('bold','bolder','lighter'): weight=('700' if ox.minify and lv=='bold' else lv)
            elif lv=='normal': pass
            elif lv in ('ultra-condensed','extra-condensed','condensed','semi-condensed','semi-expanded','expanded','extra-expanded','ultra-expanded'): stretch=lv
            else: stretch=lv
        elif t.type=='NUMBER':
            weight=fmt_num(t.value)
        elif t.type=='PERCENT':
            stretch=fmt_num(t.value)+'%'
        elif t.type=='DIM':
            # oblique angle
            style='oblique '+comp_to_text_typed(c,ox)
    if family_comps is None:
        family_comps=left[size_idx+1:]
    family=process_font_family(family_comps,ox)
    parts=[]
    for x in (style,variant,weight,stretch):
        if x: parts.append(x)
    parts.append(size)
    s=' '.join(parts)
    if line_height:
        s+= (' / ' if not ox.minify else '/')+line_height
    if family: s+=' '+family
    return s

# position
def process_position(comps,ox,keep_xy=False):
    # comma layers for background-position
    out=[]
    for part in split_commas(comps):
        out.append(_position_one(part,ox,keep_xy))
    return (', ' if not ox.minify else ',').join(out)

def _position_one(comps,ox,keep_xy=False):
    mu=meaningful(comps)
    vals=[]
    for c in mu:
        if c.kind=='tok' and c.token.type=='PERCENT' and c.token.value==0:
            vals.append('0')
        elif c.kind=='tok' and c.token.type=='IDENT':
            vals.append(c.token.value.lower())
        else:
            vals.append(comp_to_text_typed(c,ox))
    if keep_xy:
        return ' '.join(vals)
    # normalize
    if len(vals)==2:
        a,b=vals
        # center center -> center
        # keyword order swap if vertical first (top center -> center top?) reference likely keeps canonical x y
        vert={'top','bottom'}; horiz={'left','right'}
        if a in vert and (b in horiz or b=='center'):
            a,b=b,a
        if ox.minify:
            mp={'center':'50%','left':'0','right':'100%','top':'0','bottom':'100%'}
            # only replace a keyword if representation shorter/equal? center->50%, left->0 (1<4), right 100%(4<5), top->0
            # But if both become percentages, need keep two. Reference background-position:center -> 50% single after dedup.
            a2=mp.get(a,a); b2=mp.get(b,b)
            if a2==b2: return a2
            return f"{a2} {b2}"
        if a==b:
            return a
        return f"{a} {b}"
    if len(vals)==1:
        a=vals[0]
        if ox.minify:
            mp={'center':'50%','left':'0','right':'100%','top':'0','bottom':'100%'}
            # top/bottom alone means x=center, cannot convert to just 0. Keep top/bottom.
            if a in ('center','left','right'): return mp[a]
        return a
    # 3/4 values (edge offsets) keep
    return ' '.join(vals)

def process_border_value(comps,ox):
    cv=classify_border(comps,ox)
    if cv is None: return None
    return border_text(cv,ox)

def classify_border(comps,ox):
    mu=meaningful(comps)
    styles={'none','hidden','dotted','dashed','solid','double','groove','ridge','inset','outset'}
    width=None; style=None; color=None
    i=0
    # need scan comps; a color function one comp, hash one, width dimension/number/calc
    for c in mu:
        col=parse_color_from_comps([c],ox)
        if col is not None:
            color=col.to_css(ox.minify,ox.targets); continue
        if c.kind=='tok' and c.token.type=='IDENT':
            lv=c.token.value.lower()
            if lv in styles: style=lv; continue
            if lv in ('thin','medium','thick'): width=lv; continue
            if lv=='currentcolor': color='currentColor'; continue
            return None
        # width candidate
        txt=comp_to_text_typed(c,ox)
        width=txt
    if width is None and style is None and color is None: return None
    return (width,style,color)

def border_text(cv,ox):
    w,s,col=cv
    # omit defaults: medium width, none style unless it's the only, currentColor
    parts=[]
    if w is not None and w!='medium': parts.append(w)
    if s is not None:
        if not (s=='none' and (w is not None or col is not None)):
            parts.append(s)
        elif w is None and col is None:
            parts.append(s)
    if col is not None and col!='currentColor': parts.append(col)
    if not parts:
        # all defaults -> what would reference print? border:medium none currentColor probably 'none'? Keep first nonnone
        return s or w or col or ''
    # special: if width is 0 and only width originally, keep 0
    return ' '.join(parts)

def process_flex(comps,ox):
    mu=meaningful(comps)
    texts=[comp_to_text_typed(c,ox) for c in mu]
    if len(texts)==1 and texts[0] in ('none','auto','initial','content'): return texts[0]
    return flex_text_from(texts)

def flex_text_from(texts):
    # texts components (not rebuilt commas)
    vals=texts[:]
    def isnum(s):
        try: float(s); return True
        except Exception: return False
    grow=None; shrink=None; basis=None
    nums=[v for v in vals if isnum(v)]
    nons=[v for v in vals if not isnum(v)]
    if len(vals)==3 and isnum(vals[0]) and isnum(vals[1]):
        grow,shrink,basis=vals
    elif len(vals)==2:
        if isnum(vals[0]) and isnum(vals[1]): grow,shrink,basis=vals[0],vals[1],'0%'
        elif isnum(vals[0]): grow,shrink,basis=vals[0],'1',vals[1]
        else: return ' '.join(vals)
    elif len(vals)==1:
        if isnum(vals[0]): return vals[0]
        return vals[0]
    else:
        return ' '.join(vals)
    return flex_from_parts(grow,shrink,basis)

def flex_from_parts(grow,shrink,basis):
    if grow=='1' and shrink=='1' and basis=='auto': return 'auto'
    if grow=='0' and shrink=='0' and basis=='auto': return 'none'
    if shrink=='1' and basis=='0%': return grow
    if basis=='0%': basis='0'
    parts=[grow]
    if not (shrink=='1' and basis in ('auto','content')):
        parts.append(shrink)
    # If basis is auto/content and shrink 1, output "grow basis" e.g. 1 auto? But 1 1 auto caught.
    if basis is not None:
        if len(parts)==1 and shrink=='1':
            parts.append(basis)
        elif len(parts)>1:
            parts.append(basis)
    return ' '.join(parts)

def process_transition(comps,ox):
    out=[]
    for part in split_commas(comps):
        mu=meaningful(part)
        prop=None; duration=None; delay=None; timing=None
        for c in mu:
            lf=comp_leaf(c,ox)
            if lf and lf.kind=='dim' and lf.unit in TIME_UNITS:
                if duration is None: duration=lf
                elif delay is None: delay=lf
                continue
            if c.kind=='func' and c.token.value.lower() in ('cubic-bezier','steps'):
                timing=comp_to_text_typed(c,ox); continue
            if c.kind=='func' and c.token.value.lower() in ('calc','min','max','clamp','var'):
                # could be duration calc - classify as duration if none
                if duration is None: duration=('text',comp_to_text_typed(c,ox))
                else: prop=comp_to_text_typed(c,ox)
                continue
            if c.kind=='tok' and c.token.type=='IDENT':
                lv=c.token.value.lower()
                if lv in ('ease','linear','ease-in','ease-out','ease-in-out','step-start','step-end'):
                    timing=lv; continue
                if prop is None: prop=lv
                else: timing=lv
                continue
            prop=comp_to_text_typed(c,ox)
        parts=[]
        if prop: parts.append(prop)
        def ttext(x):
            return x[1] if isinstance(x,tuple) else format_time(time_to_s(x.value,x.unit))
        dur_zero = duration is not None and not isinstance(duration,tuple) and time_to_s(duration.value,duration.unit)==0
        delay_zero = delay is None or (not isinstance(delay,tuple) and time_to_s(delay.value,delay.unit)==0)
        if duration is not None and not (dur_zero and delay_zero and (timing is None or timing=='ease')):
            parts.append(ttext(duration))
            if timing and timing!='ease': parts.append(timing)
            if delay is not None and not delay_zero: parts.append(ttext(delay))
        else:
            if timing and timing!='ease':
                # need duration placeholder? transition: all ease-in (duration 0 omitted??) reference might print 'all 0s ease-in'? Keep timing after prop without duration is invalid shorthand ambiguous (timing could parse). It is allowed order any.
                parts.append(timing)
            if delay is not None and not delay_zero: parts.append(ttext(delay))
        out.append(' '.join(parts))
    return (', ' if not ox.minify else ',').join(out)

def process_animation(comps,ox):
    out=[]
    timings={'ease','linear','ease-in','ease-out','ease-in-out','step-start','step-end'}
    dirs={'normal','reverse','alternate','alternate-reverse'}
    fills={'forwards','backwards','both'}
    plays={'running','paused'}
    for part in split_commas(comps):
        mu=meaningful(part)
        duration=None; delay=None; timing=None; iteration=None; direction=None; fill=None; play=None; name=None
        for c in mu:
            lf=comp_leaf(c,ox)
            if lf and lf.kind=='dim' and lf.unit in TIME_UNITS:
                if duration is None: duration=lf
                elif delay is None: delay=lf
                continue
            if lf and lf.kind=='number' and c.kind=='tok':
                iteration=fmt_num(lf.value); continue
            if c.kind=='func':
                timing=comp_to_text_typed(c,ox); continue
            if c.kind=='tok' and c.token.type=='IDENT':
                lv=c.token.value.lower(); orig=c.token.value
                if lv in timings: timing=lv
                elif lv=='infinite': iteration='infinite'
                elif lv in dirs and lv!='normal': direction=lv
                elif lv=='normal': direction=None
                elif lv in fills: fill=lv
                elif lv=='none':
                    if name is None: name='none'
                    else: fill='none'
                elif lv in plays and lv!='running': play=lv
                elif lv=='running': play=None
                else: name=orig
                continue
            if c.kind=='tok' and c.token.type=='STRING':
                name=serialize_string(c.token.value); continue
            name=comp_to_text_typed(c,ox)
        parts=[]
        def ttext(x): return format_time(time_to_s(x.value,x.unit))
        if duration is not None: parts.append(ttext(duration))
        if timing and timing!='ease': parts.append(timing)
        if delay is not None and time_to_s(delay.value,delay.unit)!=0: parts.append(ttext(delay))
        if iteration and iteration!='1': parts.append(iteration)
        if direction: parts.append(direction)
        if fill and fill!='none': parts.append(fill)
        if play: parts.append(play)
        if name: parts.append(name)
        if not parts and name=='none': parts=['none']
        out.append(' '.join(parts))
    return (', ' if not ox.minify else ',').join(out)

def process_transform(comps,ox):
    mu=meaningful(comps)
    if len(mu)==1 and mu[0].kind=='tok' and mu[0].token.type=='IDENT' and mu[0].token.value.lower()=='none':
        return 'none'
    funcs=[]
    for c in mu:
        if c.kind!='func':
            return comps_to_text_typed(comps,ox)
        funcs.append(transform_func_text(c,ox))
    return ''.join(funcs)

def transform_func_text(c,ox):
    name=c.token.value; lname=name.lower()
    comma=', ' if not ox.minify else ','
    args_parts=split_commas(c.children)
    args=[comps_to_text_typed(p,ox) for p in args_parts]
    if lname=='translate':
        if len(args)==2 and args[1]=='0': args=args[:1]
    if lname=='scale':
        if len(args)==2 and args[0]==args[1]: args=args[:1]
    if lname=='scale3d':
        pass
    disp=CANON_FUNCS.get(lname,lname)
    if ox.minify and lname=='translatex': disp='translate'
    if ox.minify and lname=='translate' and len(args)==1:
        pass
    return f"{disp}({comma.join(args)})"

def process_shadow(comps,ox,base):
    if len(meaningful(comps))==1 and meaningful(comps)[0].kind=='tok' and meaningful(comps)[0].token.value.lower()=='none' if meaningful(comps)[0].kind=='tok' else False:
        return 'none'
    outs=[]
    for part in split_commas(comps):
        mu=meaningful(part); inset=False; lengths=[]; color=None
        for c in mu:
            col=parse_color_from_comps([c],ox)
            if col is not None: color=col.to_css(ox.minify,ox.targets); continue
            if c.kind=='tok' and c.token.type=='IDENT' and c.token.value.lower()=='inset': inset=True; continue
            if c.kind=='tok' and c.token.type=='IDENT' and c.token.value.lower()=='currentcolor': color='currentColor'; continue
            lengths.append(comp_to_text_typed(c,ox))
        # remove trailing zero blur/spread beyond 2 lengths
        if base=='box-shadow':
            while len(lengths)>2 and lengths[-1]=='0': lengths.pop()
        else:
            while len(lengths)>2 and lengths[-1]=='0': lengths.pop()
        parts=[]
        if inset: parts.append('inset')
        parts.extend(lengths)
        if color: parts.append(color)
        outs.append(' '.join(parts))
    return (', ' if not ox.minify else ',').join(outs)

def process_background(comps,ox):
    layers=split_commas(comps)
    out=[]
    for li,layer in enumerate(layers):
        out.append(_background_layer(layer,ox,last=(li==len(layers)-1)))
    return (', ' if not ox.minify else ',').join(out)

def _background_layer(comps,ox,last=True):
    # split size by slash at top meaningful level
    mu=meaningful(comps)
    # find slash comp index in meaningful
    slash_idx=None
    for i,c in enumerate(mu):
        if _is_delim(c,'/'): slash_idx=i; break
    position_comps=[]; size_comps=[]
    color=None; image=None; repeat=None; attach=None; boxes=[]
    repeats={'repeat','no-repeat','repeat-x','repeat-y','space','round'}
    attachs={'scroll','fixed','local'}
    boxk={'border-box','padding-box','content-box','text'}
    before=mu[:slash_idx] if slash_idx is not None else mu
    after=mu[slash_idx+1:] if slash_idx is not None else []
    # size: first 1-2 comps of after that are size-ish (auto/cover/contain/length/percent/calc)
    size_count=0
    if slash_idx is not None:
        for c in after:
            if size_count<2 and _is_size_comp(c):
                size_comps.append(c); size_count+=1
                if size_count==1 and c.kind=='tok' and c.token.value.lower() in ('cover','contain'): size_count=2
            else: break
        after_rest=after[size_count:] if size_count<=len(after) else []
    else:
        after_rest=[]
    def classify(c):
        nonlocal color,image,repeat,attach
        col=parse_color_from_comps([c],ox)
        if col is not None and last: color=col.to_css(ox.minify,ox.targets); return
        if c.kind=='tok' and c.token.type=='IDENT':
            lv=c.token.value.lower()
            if lv in repeats:
                repeat=(repeat+' ' if repeat else '')+lv; return
            if lv in attachs: attach=lv; return
            if lv in boxk: boxes.append(lv); return
            if lv=='none': image='none'; return
        if c.kind=='tok' and c.token.type=='URL': image=url_to_css(c.token.value,ox); return
        if c.kind=='func':
            # image functions
            image=comp_to_text_typed(c,ox); return
        position_comps.append(c)
    for c in before: classify(c)
    for c in after_rest: classify(c)
    parts=[]
    if color: parts.append(color)
    if image: parts.append(image)
    pos_text=_position_one(position_comps,ox) if position_comps else None
    size_text=None
    if size_comps:
        vals=[comp_to_text_typed(c,ox) for c in size_comps]
        if len(vals)==2 and vals[0]==vals[1]: vals=vals[:1]
        size_text=' '.join(vals)
    if pos_text or size_text:
        if size_text and size_text!='auto':
            pst=pos_text if pos_text is not None else ('0 0' if not ox.minify else '0 0')
            slash=' / ' if not ox.minify else '/'
            parts.append(pst+slash+size_text)
        elif pos_text and pos_text not in ('0 0','0% 0%'):
            parts.append(pos_text)
    if repeat and repeat!='repeat': parts.append(repeat)
    if attach and attach!='scroll': parts.append(attach)
    # boxes: origin default padding-box, clip border-box. If one box given means both origin+clip that value. Print if nondefault combination
    if boxes:
        if len(boxes)==1:
            if boxes[0] not in ('border-box',): parts.append(boxes[0])
        else:
            if not (boxes[0]=='padding-box' and boxes[1]=='border-box'): parts.append(' '.join(boxes))
    return ' '.join(parts)

def _is_size_comp(c):
    if c.kind=='tok' and c.token.type=='IDENT' and c.token.value.lower() in ('auto','cover','contain'): return True
    if c.kind=='tok' and c.token.type in ('DIM','PERCENT'): return True
    if c.kind=='func': return True
    if c.kind=='tok' and c.token.type=='NUMBER': return True
    return False

