COLOR_PROPS={'color','background-color','border-color','border-top-color','border-right-color','border-bottom-color','border-left-color','border-block-color','border-inline-color','border-block-start-color','border-block-end-color','border-inline-start-color','border-inline-end-color','outline-color','text-decoration-color','text-emphasis-color','caret-color','accent-color','column-rule-color','flood-color','lighting-color','stop-color','-webkit-text-fill-color','-webkit-text-stroke-color'}
