def rename_selector_list(sels,cm,global_mode=False):
    out=[]
    for parts in sels:
        newparts=[]
        for comb,compound in parts:
            newcomp=[]
            for c in compound:
                if c[0]=='class':
                    newcomp.append(('class', c[1] if global_mode else cm.get(c[1])))
                elif c[0]=='id':
                    newcomp.append(('id', c[1] if global_mode else cm.get(c[1])))
                elif c[0]=='pseudo':
                    _,name,is_elem,arg=c
                    if name in ('global','local') and arg and arg[0]=='selectorlist':
                        gm=(name=='global')
                        sub=rename_selector_list(arg[1],cm,global_mode=gm)
                        # flatten: global/local argument is usually a compound; if single complex with single part, splice compound
                        if len(sub)==1 and len(sub[0])==1 and sub[0][0][0] is None:
                            newcomp.extend(sub[0][0][1])
                        else:
                            # keep as :is? Reference unwraps to full selector inserted: complicated; fallback keep pseudo with renamed sub
                            newcomp.append(('pseudo',name,is_elem,('selectorlist',sub)))
                    elif arg and arg[0]=='selectorlist':
                        newcomp.append(('pseudo',name,is_elem,('selectorlist',rename_selector_list(arg[1],cm,global_mode))))
                    elif arg and arg[0]=='compound':
                        # host/slotted: rename inner as a selectorlist single
                        sub=rename_selector_list([[(None,arg[1])]],cm,global_mode)
                        newcomp.append(('pseudo',name,is_elem,('compound',sub[0][0][1])))
                    elif arg and arg[0]=='nth' and arg[3]:
                        newcomp.append(('pseudo',name,is_elem,('nth',arg[1],arg[2],rename_selector_list(arg[3],cm,global_mode))))
