def siphash13(data):
    # Rust SipHash13 with keys 0, used by DefaultHasher for str (caller appends 0xff)
    v0=0x736f6d6570736575; v1=0x646f72616e646f6d; v2=0x6c7967656e657261; v3=0x7465646279746573
    mask=(1<<64)-1
    def rot(x,n): return ((x<<n)|(x>>(64-n)))&mask
    def rnd(v0,v1,v2,v3):
        v0=(v0+v1)&mask; v1=rot(v1,13); v1^=v0; v0=rot(v0,32)
        v2=(v2+v3)&mask; v3=rot(v3,16); v3^=v2
        v0=(v0+v3)&mask; v3=rot(v3,21); v3^=v0
        v2=(v2+v1)&mask; v1=rot(v1,17); v1^=v2; v2=rot(v2,32)
        return v0,v1,v2,v3
    n=len(data); i=0; last=(n&0xff)<<56
    while i+8<=n:
        m=struct.unpack('<Q',data[i:i+8])[0]; v3^=m; v0,v1,v2,v3=rnd(v0,v1,v2,v3); v0^=m; i+=8
    for j,ch in enumerate(data[i:]): last|=ch<<(8*j)
    v3^=last; v0,v1,v2,v3=rnd(v0,v1,v2,v3); v0^=last; v2^=0xff
    for _ in range(3): v0,v1,v2,v3=rnd(v0,v1,v2,v3)
    return v0^v1^v2^v3

