        if j>i: segs.append(('lit',pat[i:j]))
        k=pat.find(']',j)
        if k==-1: raise PatternError(f"unclosed brackets at index {len(pat[:j].encode('utf-8'))}")
        ph=pat[j:k+1]
        if ph not in ('[hash]','[name]','[local]'):
            raise PatternError(f'unknown placeholder "{ph}" at index {len(pat[:j].encode("utf-8"))}')
        segs.append((ph[1:-1],None)); i=k+1
    return segs

