            # rebuild tokens from children comps by raw text then selector-parse text tokens
            inner_toks=[]
            _collect_tokens(c.children,inner_toks)
            dummy=None
            try:
                src_tokens=inner_toks
                sp=SelectorParser(src_tokens,None,ox)
                # SelectorParser requires source for errors; use a fake minimal source
                class FakeSrc:
