        elif c.kind=='tok' and c.token.type=='IDENT': parts.append(c.token.value.lower())
        else: parts.append(comp_to_text_typed(c,ox))
    return ' '.join(parts)

def _collect_tokens(comps,out):
    for c in comps:
        if c.kind=='tok':
            if c.token.type not in ('WS',): out.append(c.token)
        elif c.kind=='func':
            out.append(c.token); _collect_tokens(c.children,out); out.append(Token('RPAREN',')'))
        elif c.kind=='block':
            out.append(c.token); _collect_tokens(c.children,out)
            close={'LPAREN':'RPAREN','LBRACK':'RBRACK','LBRACE':'RBRACE'}.get(c.token.type)
            if close: out.append(Token(close,''))

