# ---------- CLI ----------
HELP_TEMPLATE = """lightningcss 1.0.0-alpha.70
Devon Govett <devongovett@gmail.com>
A CSS parser, transformer, and minifier

USAGE:
    {bin} [OPTIONS] [INPUT_FILE]...

ARGS:
    <INPUT_FILE>...    Target CSS file (default: stdin)

OPTIONS:
        --browserslist


        --bundle


        --css-modules [<CSS_MODULES>]
            Enable CSS modules in output. If no filename is provided, <output_file>.json will be
            used. If no --output-file is specified, code and exports will be printed to stdout as
            JSON

        --css-modules-dashed-idents


        --css-modules-pattern <CSS_MODULES_PATTERN>


        --custom-media
            Enable parsing custom media queries

    -d, --output-dir <OUTPUT_DIR>
            Destination directory to output into

        --error-recovery


    -h, --help
            Print help information

    -m, --minify
            Minify the output

    -o, --output-file <OUTPUT_FILE>
            Destination file for the output

        --sourcemap
            Enable sourcemap, at <output_file>.map

    -t, --targets <TARGETS>


    -V, --version
            Print version information
"""

ARG_DISPLAY={
 'browserslist':'--browserslist','bundle':'--bundle','css-modules':'--css-modules [<CSS_MODULES>]','css-modules-dashed-idents':'--css-modules-dashed-idents','css-modules-pattern':'--css-modules-pattern <CSS_MODULES_PATTERN>','custom-media':'--custom-media','output-dir':'--output-dir <OUTPUT_DIR>','error-recovery':'--error-recovery','help':'--help','minify':'--minify','output-file':'--output-file <OUTPUT_FILE>','sourcemap':'--sourcemap','targets':'--targets <TARGETS>','version':'--version'
}
LONG_ARGS=list(ARG_DISPLAY.keys())
VALUE_ARGS={'css-modules-pattern','output-dir','output-file','targets'}
LONG_MAP={k:k for k in LONG_ARGS}

def bin_name(argv0):
    b=os.path.basename(argv0) if argv0 else 'executable'
    return b or 'executable'

def print_help(bin_):
    sys.stdout.write(HELP_TEMPLATE.replace('{bin}',bin_))

def jaro(s1,s2):
    if s1==s2: return 1.0
    len1,len2=len(s1),len(s2)
    if len1==0 or len2==0: return 0.0
    match_dist=max(len1,len2)//2-1
    if match_dist<0: match_dist=0
    s1m=[False]*len1; s2m=[False]*len2; matches=0
    for i in range(len1):
        lo=max(0,i-match_dist); hi=min(len2,i+match_dist+1)
        for j in range(lo,hi):
            if not s2m[j] and s1[i]==s2[j]: s1m[i]=s2m[j]=True; matches+=1; break
    if matches==0: return 0.0
    t=0; k=0
    for i in range(len1):
        if s1m[i]:
            while not s2m[k]: k+=1
            if s1[i]!=s2[k]: t+=1
            k+=1
    t//=2
    return (matches/len1+matches/len2+(matches-t)/matches)/3
def jaro_winkler(s1,s2):
    j=jaro(s1,s2); prefix=0
    for a,b in zip(s1,s2):
        if a==b and prefix<4: prefix+=1
        else: break
    return j+prefix*0.1*(1-j)

def smart_usage(bin_, relevant, required, has_positional):
    # relevant: list of arg keys in order; required: list of descriptors ('group_output','css_modules' or a key)
    parts=[]
    i=0; rel=list(relevant)
    def add_group_for(key):
        if key in ('targets','browserslist'): return '<--targets <TARGETS>|--browserslist>'
        if key in ('output-file','output-dir'): return '<--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>'
        return None
    seen_parts=set()
    for key in rel:
        g=add_group_for(key)
        if g:
            if g in seen_parts: continue
            # Only use group form if the other member is also relevant/required or key is in a required context/suggestion/conflict.
            other={'targets':'browserslist','browserslist':'targets','output-file':'output-dir','output-dir':'output-file'}[key]
            if other in rel or 'group_output' in required or key in ('targets','browserslist') and False:
                parts.append(g); seen_parts.add(g); continue
            # for suggestion of targets, reference used group form; the caller can force by including a sentinel in required
            if 'force_group' in required:
                parts.append(g); seen_parts.add(g); continue
        disp=ARG_DISPLAY[key]
        if disp in seen_parts: continue
        parts.append(disp); seen_parts.add(disp)
    for req in required:
        if req=='force_group': continue
        if req=='group_output':
            g='<--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>'
            if g not in seen_parts: parts.append(g); seen_parts.add(g)
        elif req=='css_modules_req':
            g='<--css-modules [<CSS_MODULES>]>'
            if g not in seen_parts: parts.append(g); seen_parts.add(g)
    if has_positional: parts.append('<INPUT_FILE>...')
    if not parts: return '[OPTIONS] [INPUT_FILE]...'
    return ' '.join(parts)

class CliExit(Exception):
    def __init__(self,code): self.code=code

def cli_error(msg, bin_, usage_parts=None, bare_usage=False, suggestion=None, supply_hint=None):
    out=f"error: {msg}\n\n"
    if suggestion: out+=f"\tDid you mean '--{suggestion}'?\n\n"
    if supply_hint: out+=f"\tIf you tried to supply `{supply_hint}` as a value rather than a flag, use `-- {supply_hint}`\n\n"
    if bare_usage is not None and bare_usage is not False:
        out+=f"{bin_} {bare_usage}\n\n"
    elif usage_parts is not None:
        out+=f"USAGE:\n    {bin_} {usage_parts}\n\n"
    out+="For more information try --help\n"
    sys.stderr.write(out)
    raise CliExit(2)

@dataclass
class Args:
    browserslist: bool=False
    bundle: bool=False
    css_modules_present: bool=False
    css_modules_value: object=None  # None means present without value vs string
    css_modules_dashed: bool=False
    css_modules_pattern: object=None
    custom_media: bool=False
    output_dir: object=None
    error_recovery: bool=False
    minify: bool=False
    output_file: object=None
    sourcemap: bool=False
    targets: object=None
    inputs: list=field(default_factory=list)

def is_option_like(s):
    return len(s)>1 and s.startswith('-')

def parse_args(argv):
    bin_=bin_name(argv[0] if argv else 'executable')
    a=Args(); seen=[]  # list keys in order encountered (duplicates allowed but unique position first?)
    def mark(key):
        if key not in seen: seen.append(key)
        else:
            # keep order by first occurrence for conflict ordering? Clap indexes by arg order likely first.
            pass
    end_opts=False; i=1; n=len(argv)
    def missing_value(key):
        disp=ARG_DISPLAY[key]
        cli_error(f"The argument '{disp}' requires a value but none was supplied",bin_,usage_parts=None)
    def unknown_long(orig_name):
        # find suggestion
        suggestion=None; best=0.8
        for cand in LONG_ARGS:
            conf=jaro_winkler(orig_name,cand)
            if conf>best: best=conf; suggestion=cand
        relevant=list(seen)
        required=[]
        if suggestion:
            if suggestion not in relevant: relevant=relevant+[suggestion]
            required=['force_group']
        usage=smart_usage(bin_,relevant,required,has_positional=len(a.inputs)>0)
        cli_error(f"Found argument '--{orig_name}' which wasn't expected, or isn't valid in this context",bin_,usage_parts=usage,suggestion=suggestion,supply_hint='--'+orig_name)
    def unknown_short(ch):
        usage=smart_usage(bin_,list(seen),[],has_positional=len(a.inputs)>0)
        cli_error(f"Found argument '-{ch}' which wasn't expected, or isn't valid in this context",bin_,usage_parts=usage,supply_hint='-'+ch)
    def unexpected_value(val,key):
        disp='--'+key
        out=f"error: The value '{val}' was provided to '{disp}' but it wasn't expecting any more values\n\n{bin_} [OPTIONS] [INPUT_FILE]...\n\nFor more information try --help\n"
        sys.stderr.write(out); raise CliExit(2)
    def set_flag(key):
        mark(key)
        if key=='browserslist': a.browserslist=True
        elif key=='bundle': a.bundle=True
        elif key=='css-modules-dashed-idents': a.css_modules_dashed=True
        elif key=='custom-media': a.custom_media=True
        elif key=='error-recovery': a.error_recovery=True
        elif key=='minify': a.minify=True
        elif key=='sourcemap': a.sourcemap=True
    def set_value(key,val):
        mark(key)
        if key=='css-modules-pattern': a.css_modules_pattern=val
        elif key=='output-dir': a.output_dir=val
        elif key=='output-file': a.output_file=val
        elif key=='targets': a.targets=val
    while i<n:
        arg=argv[i]
        if not end_opts and arg=='--':
            end_opts=True; i+=1; continue
        if not end_opts and arg.startswith('--') and len(arg)>2:
            body=arg[2:]
            if '=' in body: name,val=body.split('=',1); has_eq=True
            else: name,val=body,None; has_eq=False
            if name not in LONG_MAP:
                unknown_long(name)
            key=name
            if key=='help':
                if has_eq: unexpected_value(val,key)
                print_help(bin_); raise CliExit(0)
            if key=='version':
                if has_eq: unexpected_value(val,key)
                sys.stdout.write(VERSION+'\n'); raise CliExit(0)
            if key=='css-modules':
                mark(key); a.css_modules_present=True
                if has_eq: a.css_modules_value=val
                else:
                    if i+1<n and not is_option_like(argv[i+1]) and argv[i+1]!='--':
                        a.css_modules_value=argv[i+1]; i+=1
                    else: a.css_modules_value=None
                i+=1; continue
            if key in VALUE_ARGS:
                if has_eq: set_value(key,val)
                else:
                    if i+1>=n or is_option_like(argv[i+1]):
                        missing_value(key)
                    set_value(key,argv[i+1]); i+=1
                i+=1; continue
            # flag
            if has_eq: unexpected_value(val,key)
            set_flag(key); i+=1; continue
        if not end_opts and arg.startswith('-') and arg!='-' and len(arg)>1:
            # short cluster
            j=1
            while j<len(arg):
                ch=arg[j]
                if ch=='h':
                    print_help(bin_); raise CliExit(0)
                if ch=='V':
                    sys.stdout.write(VERSION+'\n'); raise CliExit(0)
                if ch=='m':
                    set_flag('minify'); j+=1; continue
                if ch in ('d','o','t'):
                    key={'d':'output-dir','o':'output-file','t':'targets'}[ch]
                    rest=arg[j+1:]
                    if rest.startswith('='): v=rest[1:]
                    elif rest: v=rest
                    else:
                        if i+1>=n or is_option_like(argv[i+1]): missing_value(key)
                        v=argv[i+1]; i+=1
                    set_value(key,v); j=len(arg); break
                unknown_short(ch)
            i+=1; continue
        a.inputs.append(arg); i+=1
    # conflicts
    conflict_pairs=[('targets','browserslist'),('output-file','output-dir')]
    potential=[]
    for x,y in conflict_pairs:
        if x in seen and y in seen:
            first=x if seen.index(x)<seen.index(y) else y
            second=y if first==x else x
            potential.append((max(seen.index(x),seen.index(y)),first,second))
    if potential:
        potential.sort(); _,first,second=potential[0]
        usage=smart_usage(bin_,seen,['force_group'],has_positional=len(a.inputs)>0)
        cli_error(f"The argument '{ARG_DISPLAY[first]}' cannot be used with '{ARG_DISPLAY[second]}'",bin_,usage_parts=usage)
    # required
    reqs=[]  # list (order_index, descriptor_text, req_key)
    if ('css-modules-pattern' in seen or 'css-modules-dashed-idents' in seen) and 'css-modules' not in seen:
        oi=min([seen.index(k) for k in ('css-modules-pattern','css-modules-dashed-idents') if k in seen])
        reqs.append((oi,'<--css-modules [<CSS_MODULES>]>','css_modules_req'))
    if 'sourcemap' in seen and not ('output-file' in seen or 'output-dir' in seen):
        reqs.append((seen.index('sourcemap'),'<--output-file <OUTPUT_FILE>|--output-dir <OUTPUT_DIR>>','group_output'))
    if reqs:
        reqs.sort()
        msg='The following required arguments were not provided:\n'+'\n'.join('    '+r[1] for r in reqs)
        usage=smart_usage(bin_,seen,[r[2] for r in reqs],has_positional=len(a.inputs)>0)
        cli_error(msg,bin_,usage_parts=usage)
    a._seen=seen; a._bin=bin_
    return a

# ---------- runtime ----------
def main(argv=None):
    if argv is None: argv=sys.argv
    try:
        args=parse_args(argv)
    except CliExit as e:
        return e.code
    return run(args)

def run(args):
    inputs=args.inputs if args.inputs else [None]
    if len(inputs)>1:
        if args.output_file is not None:
            sys.stderr.write('Cannot use the --output-file option with multiple inputs. Use --output-dir instead.\n'); return 1
        if args.output_dir is None:
            sys.stderr.write('Cannot output to stdout with multiple inputs. Use --output-dir instead.\n'); return 1
    for inp in inputs:
        rc=process_one(inp,args)
        if rc!=0: return rc
    return 0

def read_input(inp):
    # returns (text, filename_for_parser) or raises OSError/UnicodeDecodeError
    if inp is None:
        data=sys.stdin.buffer.read()
        text=data.decode('utf-8')
        return text, f"stdin-{os.getpid()}"
    else:
        data=open(inp,'rb').read()
        text=data.decode('utf-8')
        fname=os.path.relpath(os.path.realpath(inp), os.getcwd())
        return text, fname

def process_one(inp,args):
    ox=Ox(); ox.minify=args.minify; ox.custom_media=args.custom_media; ox.error_recovery=args.error_recovery; ox.sourcemap=args.sourcemap
    # read
    try:
        text, filename = read_input(inp)
    except Exception as e:
        return io_fail(e)
    # css modules pattern parse (after read)
    css_cfg=None; pattern_segs=None
    if args.css_modules_present:
        pat=args.css_modules_pattern if args.css_modules_pattern is not None else '[hash]_[local]'
        try:
            pattern_segs=parse_pattern(pat)
        except PatternError as e:
            sys.stderr.write(f"Error parsing CSS modules pattern: {e}\n"); return 1
        css_cfg={'pattern_segs':pattern_segs,'pattern':pat,'dashed':args.css_modules_dashed,'source_filename':filename}
        ox.css_modules=css_cfg
    # parse or bundle
    sheet=None; sources_for_map=[]
    if args.bundle:
        if inp is None:
            # bundler tries to resolve stdin-PID path
            e=OSError(2,os.strerror(2))
            panic_at('src/main.rs:180:46', f'called `Result::unwrap()` on an `Err` value: Error {{ kind: ResolverError({rust_io_error(e)}), loc: None }}')
        sheet=bundle_stylesheet(inp, filename, ox)
        sources_for_map=getattr(sheet,'_bundle_sources',[])
    else:
        src=Source(filename,text)
        sources_for_map=[src]
        try:
            sheet=Parser(src,ox).parse_stylesheet()
        except ParseError as pe:
            assert not args.error_recovery
            panic_at('src/main.rs:187:45', f'called `Result::unwrap()` on an `Err` value: Error {{ kind: {pe.kind}, loc: {pe.loc_debug()} }}')
    # targets
    targets=None
    if args.browserslist:
        try:
            targets=load_browserslist_config()
        except BrowserslistError as be:
            panic_at('src/main.rs:193:39', f'called `Result::unwrap()` on an `Err` value: {be.debug}')
        except Exception as e:
            # config file read errors? surface as panic Nom approx
            panic_at('src/main.rs:193:39', 'called `Result::unwrap()` on an `Err` value: Nom("")')
    elif args.targets is not None:
        try:
            targets=parse_browserslist_query(args.targets) if args.targets.strip()!='' else {}
            if targets=={}: targets={}
        except BrowserslistError as be:
            panic_at('src/main.rs:191:56', f'called `Result::unwrap()` on an `Err` value: {be.debug}')
    ox.targets=targets
    # css modules empty pattern panic after targets
    if args.css_modules_present and pattern_segs is not None and len(pattern_segs)==0:
        panic_at('src/css_modules.rs:301:43', 'index out of bounds: the len is 0 but the index is 0')
    # process
    exports=process_stylesheet(sheet,ox)
    if args.css_modules_present and exports is None:
        exports=getattr(ox,'_cm_exports',{}) or {}
    # dest determination
    dest=None
    if args.output_file is not None:
        dest=args.output_file
    elif args.output_dir is not None:
        base=filename if inp is None else os.path.basename(inp)
        # Path file_name edge: if inp ends with / basename may be '' - read would have failed for dirs
        dest=os.path.join(args.output_dir, base)
    # print to generate code + sourcemap
    printer=print_stylesheet(sheet,ox,sources_for_map)
    code=printer.result()
    if dest is not None:
        # sourcemap first
        if args.sourcemap:
            map_path=dest+'.map'
            try:
                with open(map_path,'w',encoding='utf-8') as f: f.write(printer.sourcemap_json())
            except Exception as e:
                return io_fail(e)
            code_out=code+f"\n/*# sourceMappingURL={map_path} */\n"
        else:
            code_out=code
        # write css (create parent / output dir)
        try:
            if args.output_dir is not None:
                # Rust create_dir_all semantics
                _create_dir_all(args.output_dir)
            elif args.output_file is not None:
                parent=os.path.dirname(args.output_file)
                if parent: _create_dir_all(parent)
            with open(dest,'w',encoding='utf-8') as f: f.write(code_out)
        except Exception as e:
            return io_fail(e)
        # css modules exports file
        if args.css_modules_present:
            if args.css_modules_value is not None:
                exp_path=args.css_modules_value
            else:
                exp_path=_with_extension(dest,'json')
            exp_text=exports_file_json(exports or {})
            try:
                with open(exp_path,'w',encoding='utf-8') as f: f.write(exp_text)
            except Exception as e:
                return io_fail(e)
        return 0
    else:
        if args.css_modules_present:
            obj={'code':code,'exports':exports_stdout(exports or {})}
            sys.stdout.write(json.dumps(obj,ensure_ascii=False,separators=(',',':'),sort_keys=True)+'\n')
        else:
            sys.stdout.write(code+'\n')
        return 0

def _create_dir_all(path):
    if path=='' : return
    try:
        os.makedirs(path, exist_ok=True)
    except FileExistsError as e:
        # Rust create_dir_all on a file gives AlreadyExists; makedirs exist_ok raises FileExistserror/NotADirectory depending
        raise
    if os.path.exists(path) and not os.path.isdir(path):
        raise OSError(17, os.strerror(17))

def _with_extension(path,ext):
    # Rust Path::with_extension
    d=os.path.dirname(path); b=os.path.basename(path)
    if b in ('.','..'): return path+'.'+ext
    if b.startswith('.') and b.count('.')==1:
        nb=b+'.'+ext
    elif '.' in b:
        nb=b.rsplit('.',1)[0]+'.'+ext
    else:
        nb=b+'.'+ext
    return os.path.join(d,nb) if d else nb

def exports_stdout(exports):
    return exports

def exports_file_json(exports):
    # struct field order name, composes, isReferenced; outer insertion order
    # Manual serialization to preserve field order (json.dumps preserves dict order if we rebuild)
    out={}
    for k,v in exports.items():
        comps=[]
        for c in v.get('composes',[]):
            nc={}
            # struct order unknown for dependency entries; use name, type, loc order if present
            if 'name' in c: nc['name']=c['name']
            if 'type' in c: nc['type']=c['type']
            if 'loc' in c: nc['loc']=c['loc']
            for kk,vv in c.items():
                if kk not in nc: nc[kk]=vv
            comps.append(nc)
        out[k]={'name':v.get('name'),'composes':comps,'isReferenced':v.get('isReferenced',False)}
    return json.dumps(out,ensure_ascii=False,separators=(',',':'))

if __name__=='__main__':
    try:
        sys.exit(main())
    except BrokenPipeError:
        os.abort()

