    if keep_xy: return ' '.join(raw)
    if len(raw)==2:
        a,b=raw
        vert={'top','bottom'}; horiz={'left','right'}
        if a in vert and (b in horiz or b=='center'): a,b=b,a
        def sem(v):
            return {'left':'0','top':'0','right':'100%','bottom':'100%','center':'CENTER'}.get(v,v)
        sa,sb=sem(a),sem(b)
        def render(sv,sole=False):
            if sv=='CENTER': return 'center' if sole and not ox.minify else '50%'
            return sv
        if sb=='CENTER' or sb=='50%':
            return render(sa,sole=True)
        return f"{render(sa)} {render(sb)}"
    if len(raw)==1:
