def _border_optimize(items,ox):
    sides=['top','right','bottom','left']
    # collect
    data={side:{} for side in sides}; used=set(); template=None
    for it in items:
        n=it.name
        matched=False
        for side in sides:
            if n==f'border-{side}-width': data[side]['width']=it.text; matched=True
            elif n==f'border-{side}-style': data[side]['style']=it.text; matched=True
            elif n==f'border-{side}-color': data[side]['color']=it.text; matched=True
            elif n==f'border-{side}':
                cv=classify_border(it.comps,ox)
                if cv is None: return items
                w,st,col=cv; data[side]['width']=w or 'medium'; data[side]['style']=st or 'none'; data[side]['color']=col or 'currentColor'; matched=True
        if matched:
            used.add(id(it)); template=template or it
    if not all(all(k in data[side] for k in ('width','style','color')) for side in sides):
        return items
    # bail if other border items exist not used
    if any((it.name.startswith('border') and id(it) not in used) for it in items):
        return items
    tuples={side:(data[side]['width'],data[side]['style'],data[side]['color']) for side in sides}
    def mk(name,text):
        nd=_clone_decl(template,name=name,text=text); nd.order=template.order; return nd
    candidates=[]
    # A four sides order top,bottom,left,right
    candidates.append([mk(f'border-{side}',border_text(tuples[side],ox)) for side in ['top','bottom','left','right']])
    # B three boxes
    bw=box_reduce([tuples[s][0] for s in sides]); bs=box_reduce([tuples[s][1] for s in sides]); bc=box_reduce([tuples[s][2] for s in sides])
    candidates.append([mk('border-width',' '.join(bw)),mk('border-style',' '.join(bs)),mk('border-color',' '.join(bc))])
    # C/D for each unique base tuple in order of sides top,right,bottom,left
    uniq=[]
    for side in sides:
        if tuples[side] not in uniq: uniq.append(tuples[side])
    for base in uniq:
        # a side shorthands
        cand=[mk('border',border_text(base,ox))]
        for side in ['top','bottom','left','right']:
            if tuples[side]!=base: cand.append(mk(f'border-{side}',border_text(tuples[side],ox)))
        candidates.append(cand)
        # b dimension longhands
        cand=[mk('border',border_text(base,ox))]
        for side in ['top','bottom','left','right']:
            for di,dim in enumerate(('width','style','color')):
                if tuples[side][di]!=base[di]: cand.append(mk(f'border-{side}-{dim}',tuples[side][di]))
        candidates.append(cand)
    # c box overrides with base=right only
    base=tuples['right']; cand=[mk('border',border_text(base,ox))]
    dims=[('border-width',0),('border-style',1),('border-color',2)]
    for nm,di in dims:
