    candidates.append(cand)
    def cost(cand):
        return sum(len(d.name)+len(d.text or '')+2 for d in cand)
    best=min(candidates,key=cost)
    out=[]; inserted=False
    for it in items:
        if id(it) in used:
            if not inserted: out.extend(best); inserted=True
            continue
        out.append(it)
    return out

