def _source_color_channels(col, target):
    # returns dict channel name -> numeric value in target-space native units, plus alpha 0-1
    conv=None
    rgba=None; lab=None; oklab=None
    if col.kind=='rgba':
        rgba=(col.r,col.g,col.b,col.a/255)
    else:
        conv=_parse_color_numeric(col)
        if conv is None: return None
        rgba=(conv['rgba'][0],conv['rgba'][1],conv['rgba'][2],conv['rgba'][3]/255); lab=conv['lab']
    r,g,b,a=rgba
    if target in ('rgb','rgba'):
        return {'r':r,'g':g,'b':b,'alpha':a}
    if target in ('hsl','hsla'):
        import colorsys
        h,l,s=colorsys.rgb_to_hls(r/255,g/255,b/255)
        return {'h':h*360,'s':s*100,'l':l*100,'alpha':a}
    if target=='hwb':
        import colorsys
        h,l,s=colorsys.rgb_to_hls(r/255,g/255,b/255); w=min(r,g,b)/255*100; bl=(1-max(r,g,b)/255)*100
        return {'h':h*360,'w':w,'b':bl,'alpha':a}
    if lab is None:
        lab=rgb_to_lab(r,g,b)+(a,)
    if target=='lab':
        return {'l':lab[0],'a':lab[1],'b':lab[2],'alpha':a}
    if target=='lch':
        return {'l':lab[0],'c':math.hypot(lab[1],lab[2]),'h':math.degrees(math.atan2(lab[2],lab[1]))%360,'alpha':a}
    oklab=rgb_to_oklab(r,g,b)
    if target=='oklab':
        return {'l':oklab[0]*100,'a':oklab[1],'b':oklab[2],'alpha':a}
    if target=='oklch':
        return {'l':oklab[0]*100,'c':math.hypot(oklab[1],oklab[2]),'h':math.degrees(math.atan2(oklab[2],oklab[1]))%360,'alpha':a}
    return None

def _parse_relative_color(c,ox):
    name=c.token.value.lower()
    groups=split_slash(c.children)
    main=groups[0]
    if len(main)<2: return None
    src_comp=main[1]; rest=main[2:]
    src=parse_color_from_comps([src_comp],ox)
    if src is None: return None
    chans=_source_color_channels(src,name)
    if chans is None: return None
    # channel order
    orders={'rgb':['r','g','b'],'rgba':['r','g','b'],'hsl':['h','s','l'],'hsla':['h','s','l'],'hwb':['h','w','b'],'lab':['l','a','b'],'lch':['l','c','h'],'oklab':['l','a','b'],'oklch':['l','c','h']}
    if name not in orders: return None
    order=orders[name]
    if len(rest)!=3: return None
    vals=[]
    for comp,chname in zip(rest,order):
        v=_eval_channel_comp(comp,chans,ox)
        if v is None: return None
        vals.append(v)
    alpha=chans['alpha']
    if len(groups)>1 and groups[1]:
        av=_eval_channel_comp(groups[1][0],chans,ox,is_alpha=True)
        if av is None: return None
        alpha=av
    abyte=clamp255(alpha*255) if alpha<=2 else clamp255(alpha/100*255)
    # alpha from _eval may be percent already normalized below
    if name in ('rgb','rgba'):
        return Color('rgba',clamp255(vals[0]),clamp255(vals[1]),clamp255(vals[2]),clamp255(alpha*255))
    if name in ('hsl','hsla'):
        r,g,b=hsl_to_rgb(vals[0],vals[1]/100,vals[2]/100); return Color('rgba',r,g,b,clamp255(alpha*255))
    if name=='hwb':
        r,g,b=hwb_to_rgb(vals[0],vals[1]/100,vals[2]/100); return Color('rgba',r,g,b,clamp255(alpha*255))
    alpha_obj=None if alpha>=0.999999 else f32(alpha)
    if name=='lab':
        return Color('lab',comps=[fmt_num(f32(vals[0]))+'%',fmt_num(f32(vals[1])),fmt_num(f32(vals[2]))],alpha=alpha_obj)
    if name=='lch':
        return Color('lch',comps=[fmt_num(f32(vals[0]))+'%',fmt_num(f32(vals[1])),fmt_num(f32(vals[2]%360))],alpha=alpha_obj)
    if name=='oklab':
        return Color('oklab',comps=[fmt_num(f32(vals[0]))+'%',fmt_num(f32(vals[1])),fmt_num(f32(vals[2]))],alpha=alpha_obj)
    if name=='oklch':
        return Color('oklch',comps=[fmt_num(f32(vals[0]))+'%',fmt_num(f32(vals[1])),fmt_num(f32(vals[2]%360))],alpha=alpha_obj)
    return None

def _eval_channel_comp(comp,chans,ox,is_alpha=False):
    # clone comp replacing channel ident tokens with number tokens
    import copy as _cp
    cc=_cp.deepcopy(comp)
    def replace(c):
        if c.kind=='tok' and c.token.type=='IDENT' and c.token.value.lower() in chans:
            c.token.type='NUMBER'; c.token.value=float(chans[c.token.value.lower()]); c.token.extra={'has_sign':False,'int_value':None,'is_int':False}
        if c.kind in ('func','block'):
            for ch in c.children: replace(ch)
    replace(cc)
    lf=comp_leaf(cc,ox)
    if lf is None: return None
    if is_alpha:
        if lf.kind=='percent': return lf.value/100
        if lf.kind=='number': return lf.value
        return None
    if lf.kind=='percent': return lf.value
    if lf.kind=='number': return lf.value
    if lf.kind=='dim': return angle_to_deg(lf.value,lf.unit) if lf.unit in ANGLE_UNITS else lf.value
    return None

