    pre=left[:size_idx]; i=0
    stretch_kw={'ultra-condensed','extra-condensed','condensed','semi-condensed','semi-expanded','expanded','extra-expanded','ultra-expanded'}
    variant_kw={'small-caps','all-small-caps','petite-caps','all-petite-caps','unicase','titling-caps'}
