def _recombine_font(items,ox,tmpl):
    names={'font-style','font-variant-caps','font-weight','font-stretch','font-size','line-height','font-family'}
    found={it.name:it for it in items if it.name in names}
    if 'font-size' not in found or 'font-family' not in found: return items
    def tx(n,default='normal'):
        return found[n].text if n in found else default
    parts=[]
    if tx('font-style')!='normal': parts.append(tx('font-style'))
    if tx('font-variant-caps')!='normal': parts.append(tx('font-variant-caps'))
    w=tx('font-weight')
    if w not in ('normal','400'): parts.append(w)
    if tx('font-stretch')!='normal': parts.append(tx('font-stretch'))
    size=tx('font-size')
    if tx('line-height')!='normal': size+=(' / ' if not ox.minify else '/')+tx('line-height')
