def _parse_background_shorthand(d,ox):
    comps=d.comps
    if any(c.kind=='tok' and c.token.type=='COMMA' for c in meaningful(comps)): return None
    mu=meaningful(comps)
    slash_idx=None
    for i,c in enumerate(mu):
        if _is_delim(c,'/'): slash_idx=i; break
    before=mu[:slash_idx] if slash_idx is not None else mu
    after=mu[slash_idx+1:] if slash_idx is not None else []
