        ('background-repeat',repeat if repeat else ident('repeat')),
        ('background-attachment',[attach] if attach is not None else ident('scroll')),
        ('background-origin',[origin]),
        ('background-clip',[clip]),
    ]

def _recombine_background(items,ox,tmpl):
    names={'background-color','background-image','background-position','background-size','background-repeat','background-attachment','background-origin','background-clip'}
    found={it.name:it for it in items if it.name in names}
    if not found: return items
    def tx(n,default=None): return found[n].text if n in found else default
