    color=tx('background-color')
    if color and color not in ('#0000','transparent'): parts.append(color)
    image=tx('background-image')
    if image and image!='none': parts.append(image)
    pos=tx('background-position','0 0'); size=tx('background-size','auto')
    if size and size!='auto': parts.append(pos+(' / ' if not ox.minify else '/')+size)
    elif pos and pos not in ('0 0','0% 0%'): parts.append(pos)
    rep=tx('background-repeat')
    if rep and rep!='repeat': parts.append(rep)
    att=tx('background-attachment')
    if att and att!='scroll': parts.append(att)
