    if (origin,clip)!=('padding-box','border-box'):
        parts.append(origin if origin==clip else origin+' '+clip)
    text=' '.join(parts) if parts else ('0 0' if ox.minify else 'none')
    new=_clone_decl(tmpl,name='background',text=text); new.order=min(it.order for it in found.values())
    return _replace_items(items,names,new)

