import subprocess,os,re,ast,sys
from concurrent.futures import ThreadPoolExecutor
# Parse arg lists from /tmp/argtests.txt lines starting with [
arglists=[]
for line in open('/tmp/argtests.txt'):
    line=line.strip()
    if line.startswith('['):
        # up to ] exit
        m=re.match(r"(\[.*\]) exit",line)
        if m:
            try: arglists.append(ast.literal_eval(m.group(1)))
            except Exception: pass
print(len(arglists),'arglists',file=sys.stderr)
REF=os.path.abspath('./executable'); MINE='/tmp/minebin/executable'
def run(exe,args):
    import tempfile
    tmp=tempfile.mkdtemp()
    r=subprocess.run([exe]+args,input='a{color:red}',capture_output=True,text=True,cwd=tmp)
    def norm(s): return re.sub(r"\(\d+\)","(P)",re.sub(r"stdin-\d+","S",s))
    return r.returncode,norm(r.stdout),norm(r.stderr)
def job(args):
    r1=run(REF,args); r2=run(MINE,args)
    return (args,r1,r2) if r1!=r2 else None
fails=[]
with ThreadPoolExecutor(max_workers=24) as ex:
    for r in ex.map(job,arglists):
        if r:fails.append(r)
print(f"{len(arglists)-len(fails)}/{len(arglists)} pass")
for a,r1,r2 in fails: print("\nFAIL",a,"\nREF",r1,"\nMINE",r2)
